INSERT INTO "content_info" VALUES('rules','Educational content. No pesticide products, doses, mixing or intervals: those follow the local product label.');
INSERT INTO "content_info" VALUES('review','App content is general plant-pathology knowledge, not reviewed by a plant pathologist; rows with source = ''treatment_content'' come from the reviewed treatment_content.sql.');
INSERT INTO "diseases" VALUES('tomato','early_blight','Early Blight','Fungal',NULL,'Leaf','A common fungal leaf disease of tomato and potato caused by Alternaria species.','Warm, humid conditions with extended leaf wetness; inoculum surviving on crop residue and soil.','Lesions destroy photosynthetic tissue and cause leaves to yellow and drop, weakening the plant.','Severe defoliation can expose fruit to sunscald and substantially reduce yield.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('tomato','late_blight','Late Blight','Fungal',NULL,'Leaf','A destructive oomycete disease (Phytophthora infestans) of tomato and potato.','Cool, wet, humid weather; airborne sporangia from nearby infected plants or residue.','Destroys foliage and fruit very rapidly under favourable weather.','Whole plantings can be lost within days under sustained cool, wet conditions.',3.499999940395355224e-01,0.699999988079071,2.000000029802322388e-01,1.5000000596046447754e-01);
INSERT INTO "diseases" VALUES('tomato','bacterial_spot','Bacterial Spot','Bacterial',NULL,'Leaf','A bacterial disease (Xanthomonas species) of tomato and pepper leaves, stems and fruit.','Warm, wet weather; rain or overhead-water splash; infected seed or transplants.','Spotted leaves yellow and drop; fruit is blemished.','Heavy leaf drop exposes fruit to sunscald and cuts yield.',3.499999940395355224e-01,0.699999988079071,1.8000000715255737304e-01,1.1999999731779098511e-01);
INSERT INTO "diseases" VALUES('tomato','leaf_mold','Leaf Mold','Fungal',NULL,'Leaf','A fungal disease (Passalora fulva) of tomato leaves, mostly in greenhouses and tunnels.','Very humid air (above about 85%) and leaves that stay wet; poor ventilation; spores survive on debris and structures.','Infected leaves lose their green tissue and drop, starting low on the plant.','Heavy leaf loss in a humid house cuts fruit size and yield.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('tomato','septoria_leaf_spot','Septoria Leaf Spot','Fungal',NULL,'Leaf','A fungal disease (Septoria lycopersici) that covers tomato leaves in many small spots.','Warm, wet weather; spores splash up from infected debris and soil onto the lower leaves.','Spotted leaves yellow and drop from the bottom of the plant upward.','Severe defoliation weakens the plant and leaves fruit exposed to sunscald.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('tomato','spider_mites','Spider Mites','Pest',NULL,'Leaf','Two-spotted spider mites (Tetranychus urticae): tiny sap-sucking mites, not a disease.','Hot, dry weather and dusty, water-stressed plants; mites multiply very fast in heat.','Feeding empties leaf cells; leaves bronze, dry out and drop.','Heavy infestations can strip and kill plants in hot weather.',3.499999940395355224e-01,0.699999988079071,1.1999999731779098511e-01,7.999999821186065673e-02);
INSERT INTO "diseases" VALUES('tomato','target_spot','Target Spot','Fungal',NULL,'Leaf','A fungal disease (Corynespora cassiicola) of tomato leaves, stems and fruit.','Warm, humid weather with long leaf wetness; dense canopies; spores survive on debris.','Spots merge and leaves drop, starting in the lower canopy.','Defoliation and fruit spots reduce yield and quality.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('tomato','yellow_leaf_curl_virus','Yellow Leaf Curl Virus','Viral',NULL,'Leaf','A virus (TYLCV, a begomovirus) spread by the silverleaf whitefly (Bemisia tabaci).','Whiteflies that fed on infected plants carry the virus to healthy ones; warm weather favours them.','Infected plants stop growing and set little or no fruit.','There is no cure: infected plants stay infected and are a source for the whiteflies.',3.499999940395355224e-01,0.699999988079071,4.499999880790710449e-01,3.000000119209289551e-01);
INSERT INTO "diseases" VALUES('tomato','mosaic_virus','Mosaic Virus','Viral',NULL,'Leaf','Tomato mosaic virus (ToMV), a very stable virus spread on hands, tools and seed.','Handling infected then healthy plants; infected seed; the virus survives for a long time in plant debris.','Infected plants grow poorly and yield less.','There is no cure; the virus spreads easily to the rest of the crop.',3.499999940395355224e-01,0.699999988079071,4.499999880790710449e-01,3.000000119209289551e-01);
INSERT INTO "diseases" VALUES('potato','early_blight','Early Blight','Fungal',NULL,'Leaf','A common fungal leaf disease of potato caused by Alternaria solani.','Warm, humid weather with long leaf wetness; stressed or under-fed plants; inoculum on crop debris.','Lesions destroy leaf area and weaken the plant late in the season.','Early defoliation reduces tuber size and yield.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('potato','late_blight','Late Blight','Fungal',NULL,'Leaf','A destructive water-mould disease (Phytophthora infestans) of potato and tomato.','Cool (10–25 °C), wet weather; airborne spores from nearby infected plants or cull piles.','Destroys foliage within days and can rot tubers in the ground and in store.','Whole crops can be lost in a wet week.',3.499999940395355224e-01,0.699999988079071,2.000000029802322388e-01,1.5000000596046447754e-01);
INSERT INTO "diseases" VALUES('pepper','bacterial_spot','Bacterial Spot','Bacterial',NULL,'Leaf','A bacterial disease (Xanthomonas) of pepper and tomato leaves and fruit.','Warm, wet weather; rain or overhead-water splash; infected seed or transplants.','Spotted leaves yellow and drop; fruit is blemished.','Heavy leaf drop exposes fruit to sunscald and cuts yield.',3.499999940395355224e-01,0.699999988079071,1.8000000715255737304e-01,1.1999999731779098511e-01);
INSERT INTO "diseases" VALUES('pepper','powdery_mildew','Powdery Mildew','Fungal',NULL,'Leaf','A fungal disease (Leveillula taurica) that grows inside and under pepper leaves.','Warm, dry days with humid nights; crowded plants.','Reduces leaf area and causes leaf drop.','Severe leaf loss leaves fruit sunburnt and small.',3.499999940395355224e-01,0.699999988079071,1.1999999731779098511e-01,5.999999865889549256e-02);
INSERT INTO "diseases" VALUES('pepper','blossom_end_rot','Blossom End Rot','Abiotic','Calcium shortage in the growing fruit (uneven watering)','Fruit','A disorder, not an infection: the end of the fruit away from the stalk dies because too little calcium reaches it while it grows.','Uneven watering (dry spells then heavy watering), drought, root damage or too much nitrogen keep calcium from reaching the fruit; it is rarely a lack of calcium in the soil.','Affected fruit is spoiled; later fruit is fine once watering is even.','Fruit keeps being lost while watering stays uneven.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('pepper','frogeye_leaf_spot','Frogeye Leaf Spot','Fungal','Cercospora capsici','Leaf','A fungal leaf spot of pepper with pale-centred, dark-ringed spots.','Spores survive on infected debris and seed and spread by wind and rain splash in warm, humid weather.','Leaf drop exposes fruit to sunscald and reduces yield.','Severe spotting defoliates plants.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('apple','apple_scab','Apple Scab','Fungal',NULL,'Leaf','A fungal disease (Venturia inaequalis) of apple leaves and fruit.','Cool, wet spring weather; the fungus overwinters in fallen leaves.','Infected leaves drop early; fruit is blemished and cracks.','Repeated years of leaf loss weaken the tree and cut cropping.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('apple','cedar_apple_rust','Cedar Apple Rust','Fungal',NULL,'Leaf','A rust fungus that alternates between apple trees and junipers (cedars).','Spores blow in from galls on nearby junipers during wet spring weather.','Spotted leaves drop early; fruit can be spotted and deformed.','Repeated defoliation weakens the tree.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,7.999999821186065673e-02);
INSERT INTO "diseases" VALUES('apple','black_rot','Black Rot','Fungal',NULL,'Leaf','A fungal disease (Botryosphaeria obtusa) of apple leaves, fruit and branches.','Spores from cankers, dead wood and mummified fruit spread in warm, wet weather.','Leaf spots cause some leaf drop; fruit rots on the tree.','Cankers weaken branches, and rotting fruit is lost.',3.499999940395355224e-01,0.699999988079071,1.8000000715255737304e-01,1.1999999731779098511e-01);
INSERT INTO "diseases" VALUES('apple','mosaic_virus','Apple Mosaic','Viral','Apple mosaic virus (ApMV, an ilarvirus)','Leaf','A virus disease of apple that marks the leaves with pale yellow to cream patches and bands.','The virus is carried in the tree''s sap and spreads through grafting and budding with infected wood; no insect spreads it.','Infected trees grow and crop somewhat less; the marks do not spread to healthy trees in the orchard.','The tree stays infected for life; yields of sensitive varieties fall over the years.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('blueberry','anthracnose','Anthracnose Fruit Rot','Fungal','Colletotrichum fioriniae (and C. acutatum)','Fruit','A fungal ripe rot of blueberries that shows as the fruit ripens or after picking.','The fungus overwinters on twigs and buds; rain splashes spores onto green berries, which stay symptomless until they ripen.','Ripe fruit rots on the bush and in storage.','Losses grow each wet year as the fungus builds up on the twigs.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('blueberry','botrytis_blight','Botrytis Blight','Fungal','Botrytis cinerea','Fruit','Grey mould of blueberry blossoms, young shoots and fruit.','Cool, wet weather at bloom; the fungus lives on dead plant matter and its spores are everywhere in the air.','Blighted flowers set no fruit, and berries rot.','Fruit is lost in wet springs and in storage.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('blueberry','mummy_berry','Mummy Berry','Fungal','Monilinia vaccinii-corymbosi','Fruit','A fungal disease that withers shoots in spring and turns the berries into hard, grey ''mummies''.','Mummified berries on the ground grow small cup fungi in spring; their spores blight young shoots, which then infect the flowers.','Infected berries are lost.','Mummies on the ground start the next spring''s epidemic.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('blueberry','rust','Blueberry Leaf Rust','Fungal','Thekopsora minima (syn. Pucciniastrum vaccinii)','Leaf','A rust fungus of blueberry leaves; hemlock is its alternate host.','Spores blow from nearby hemlocks or infected bushes; warm, humid weather lets them infect.','Bushes lose leaves early, so fewer flower buds form for next year.','Repeated defoliation lowers yields.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('blueberry','scorch','Blueberry Scorch','Viral','Blueberry scorch virus (BlScV, a carlavirus)','Leaf','A virus disease that blights blossoms and scorches the leaf edges of highbush blueberry.','Aphids carry the virus from infected bushes; it also travels in infected cuttings.','Fruit set fails on affected branches.','Infected bushes decline over a few years; the virus spreads along the row.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cherry','powdery_mildew','Powdery Mildew','Fungal',NULL,'Leaf','A fungal disease (Podosphaera clandestina) of cherry leaves, shoots and fruit.','Warm, humid weather with dry leaves; spores overwinter on the tree and in fallen leaves.','Infected leaves photosynthesise less and may drop; fruit is blemished.','Repeated years weaken young trees and spoil fruit.',3.499999940395355224e-01,0.699999988079071,1.1999999731779098511e-01,5.999999865889549256e-02);
INSERT INTO "diseases" VALUES('cherry','leaf_spot','Cherry Leaf Spot','Fungal','Blumeriella jaapii','Leaf','A fungal disease of cherry leaves that causes spotting, yellowing and early leaf fall.','Spores from last year''s fallen leaves are splashed onto young leaves in wet spring and summer weather.','Trees lose many leaves by midsummer, so fruit ripens poorly.','Repeated early leaf loss weakens trees and makes them prone to winter injury.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('corn','gray_leaf_spot','Gray Leaf Spot','Fungal',NULL,'Leaf','A fungal disease (Cercospora zeae-maydis) of maize leaves.','Warm, very humid weather with long dew periods; the fungus survives on maize residue left on the surface.','Dead leaf area cuts the sugar supply to the ear.','Severe epidemics cause early death of leaves, stalk rot and yield loss.',3.499999940395355224e-01,0.699999988079071,1.8000000715255737304e-01,1.1999999731779098511e-01);
INSERT INTO "diseases" VALUES('corn','common_rust','Common Rust','Fungal',NULL,'Leaf','A rust fungus (Puccinia sorghi) of maize leaves.','Spores blow in on the wind; cool to moderate temperatures and heavy dew favour infection.','Heavy rusting reduces the green leaf area.','Severe early rust on susceptible maize can reduce yield.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('corn','northern_leaf_blight','Northern Leaf Blight','Fungal',NULL,'Leaf','A fungal disease (Exserohilum turcicum) of maize leaves.','Moderate temperatures with long dew or rain; the fungus survives on maize residue.','Large lesions kill big parts of the leaves.','Heavy infection before or soon after tasselling can cut yield substantially.',3.499999940395355224e-01,0.699999988079071,1.8000000715255737304e-01,1.1999999731779098511e-01);
INSERT INTO "diseases" VALUES('corn','smut','Common Smut','Fungal','Ustilago maydis','Head','A fungal disease that turns parts of the ear, tassel or stalk into swollen galls full of black spores.','Spores survive in the soil for years and infect young, growing tissue, mostly through wounds from hail, insects or cultivation.','Infected ears are lost; the rest of the plant is usually fine.','Spores from burst galls add to the soil supply for years.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('grape','black_rot','Black Rot','Fungal',NULL,'Leaf','A fungal disease (Guignardia bidwellii) of grape leaves, shoots and berries.','Warm, wet spring and early summer weather; spores come from mummified berries and old canes.','Leaf spots are minor; infected berries are lost.','Whole bunches can be destroyed in a wet year.',3.499999940395355224e-01,0.699999988079071,1.8000000715255737304e-01,1.1999999731779098511e-01);
INSERT INTO "diseases" VALUES('grape','esca','Esca (Black Measles)','Fungal',NULL,'Leaf','A trunk disease of grapevines caused by wood-rotting fungi (Phaeomoniella chlamydospora, Phaeoacremonium species and others).','The fungi enter through pruning wounds and grow in the wood over years; leaf symptoms appear in summer.','The wood is slowly destroyed; leaves scorch and fruit is spotted.','Vines decline over years and can die suddenly; there is no cure.',3.499999940395355224e-01,0.699999988079071,4.000000059604644776e-01,3.000000119209289551e-01);
INSERT INTO "diseases" VALUES('grape','leaf_blight','Leaf Blight (Isariopsis Leaf Spot)','Fungal',NULL,'Leaf','A fungal leaf spot of grapevine (Pseudocercospora vitis, also called Isariopsis leaf spot).','Warm, humid weather late in the season; spores survive on fallen leaves.','Leaf area is lost late in the season.','Early leaf drop weakens the vine and ripening.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('grape','downy_mildew','Downy Mildew','Oomycete','Plasmopara viticola','Leaf','A water-mould disease of grapevine leaves, shoots and young berries.','Warm, wet weather: rain splashes spores from the soil and leaf litter onto leaves, which must stay wet for hours to be infected.','Infected leaves die and fall, and berry bunches can be lost.','Severe years strip vines of leaves, so fruit and wood ripen poorly.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('grape','leafroll','Grapevine Leafroll','Viral','Grapevine leafroll-associated viruses (mainly GLRaV-3)','Leaf','A virus disease of grapevines that reddens and rolls the leaves in late summer and spoils the fruit.','Spread in infected cuttings and rootstocks, and from vine to vine by mealybugs and soft scale insects.','Grapes ripen late with less sugar and poor colour.','Infected vines stay infected; yield and quality fall over the years and the disease spreads along the row.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('orange','citrus_greening','Citrus Greening (Huanglongbing)','Bacterial',NULL,'Leaf','A bacterial disease (Candidatus Liberibacter asiaticus) of citrus, spread by the Asian citrus psyllid.','Psyllids that fed on an infected tree carry the bacteria to healthy ones; infected budwood also spreads it.','The bacteria block the tree''s food-conducting tissue; roots and canopy decline.','There is no cure: infected trees decline and become unproductive.',3.499999940395355224e-01,0.699999988079071,0.5,3.499999940395355224e-01);
INSERT INTO "diseases" VALUES('orange','citrus_canker','Citrus Canker','Bacterial','Xanthomonas citri subsp. citri','Leaf','A bacterial disease of citrus leaves, twigs and fruit that leaves raised, corky spots.','Wind-driven rain spreads the bacteria; they enter through pores and wounds, including citrus leafminer tunnels.','Spotted leaves and fruit drop early; marked fruit cannot be sold fresh.','Heavy infection defoliates trees and causes large fruit losses; the disease is regulated in many countries.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('peach','bacterial_spot','Bacterial Spot','Bacterial',NULL,'Leaf','A bacterial disease (Xanthomonas arboricola pv. pruni) of peach and other stone fruit.','Warm, wet, windy weather; bacteria overwinter in twig cankers and spread by rain splash.','Leaves drop and fruit is blemished.','Repeated defoliation weakens trees and makes fruit unmarketable.',3.499999940395355224e-01,0.699999988079071,2.000000029802322388e-01,1.4000000059604644775e-01);
INSERT INTO "diseases" VALUES('peach','anthracnose','Anthracnose','Fungal','Colletotrichum spp.','Fruit','A fungal fruit rot of peach that is worst in warm, wet weather near harvest.','Spores spread by rain splash from infected fruit and nearby hosts; warm, humid weather favours it.','Infected fruit is lost, before or after harvest.','Mummified fruit carries the fungus to next season.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('peach','brown_rot','Brown Rot','Fungal','Monilinia fructicola (and M. laxa)','Fruit','A fungal disease of stone fruit that blights blossoms and rots the fruit.','Spores from mummified fruit and twig cankers infect blossoms in wet spring weather and ripening fruit near harvest, often through wounds.','Rotted fruit is lost, on the tree and in storage.','Mummies and cankers start next year''s infections.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('peach','leaf_curl','Peach Leaf Curl','Fungal','Taphrina deformans','Leaf','A fungal disease that thickens, puckers and reddens peach leaves in spring.','Spores on the bark and buds infect the leaves as the buds open in cool, wet spring weather.','The tree loses its first leaves and must regrow them, which weakens it.','Several years of heavy curl weaken the tree and cut the crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('peach','rust','Peach Rust','Fungal','Tranzschelia discolor','Leaf','A rust fungus of peach and other stone fruit leaves.','Spores blow in or survive in twig cankers; long leaf wetness in warm weather lets them infect.','Early leaf fall weakens the tree for next year.','Repeated defoliation reduces vigour and fruit size.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('peach','scab','Peach Scab','Fungal','Cladosporium carpophilum (Venturia carpophila)','Fruit','A fungal disease that freckles peach fruit with dark spots.','Spores from twig lesions infect young fruit in warm, wet weather after petal fall; spots appear weeks later.','Fruit is blemished and may crack and rot.','Twig lesions carry the fungus to next year.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('raspberry','fire_blight','Fire Blight','Bacterial','Erwinia amylovora','Leaf','A bacterial disease that blackens raspberry shoot tips and leaves, as if scorched by fire.','Bacteria spread by rain, insects and pruning tools in warm, humid weather, entering through flowers and wounds.','Blighted shoots and their fruit are lost.','Infection can move down the cane.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('raspberry','gray_mold','Gray Mold','Fungal','Botrytis cinerea','Fruit','Grey mould of raspberry fruit, the main cause of rotting berries.','The fungus lives on dead plant material; its spores infect flowers in wet weather and the berries rot as they ripen.','Fruit rots on the cane and soon after picking.','Most of a wet season''s crop can be lost.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('raspberry','leaf_spot','Leaf Spot','Fungal','Sphaerulina rubi (syn. Septoria rubi)','Leaf','A fungal leaf spot of raspberries and blackberries.','Spores from infected leaves and canes spread by rain splash in warm, wet weather.','Leaf loss weakens the canes for next season.','Cane growth and yield decline.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('raspberry','yellow_rust','Yellow Rust','Fungal','Phragmidium rubi-idaei','Leaf','A rust fungus of raspberry leaves and canes.','Spores overwinter on fallen leaves and canes and infect new leaves in spring; summer spores spread in humid weather.','Leaves fall early, weakening the canes.','Severe years reduce the next crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('soybean','rust','Soybean Rust','Fungal','Phakopsora pachyrhizi','Leaf','Asian soybean rust: a fast-spreading rust fungus that can strip soybean fields of their leaves.','Spores blow long distances on the wind; leaf wetness of 6+ hours at 15-28 °C lets them infect. The fungus does not survive cold winters.','Rapid leaf loss cuts pod fill and yield.','Unchecked epidemics can cause heavy yield losses.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('soybean','bacterial_blight','Bacterial Blight','Bacterial','Pseudomonas savastanoi pv. glycinea','Leaf','A bacterial leaf spot of soybean in cool, wet weather.','The bacteria survive in residue and seed and spread by wind-driven rain into the leaves.','Usually minor; severe cases reduce yield.','Ragged leaves in cool, wet years.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('soybean','brown_spot','Brown Spot','Fungal','Septoria glycines','Leaf','Septoria brown spot: the most common leaf spot of soybean, starting on the lower leaves.','The fungus survives on residue; rain splashes spores onto the lowest leaves in warm, wet weather.','Lower leaves drop; yield effect is usually small.','In wet seasons it climbs the plant and reduces yield.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('soybean','downy_mildew','Downy Mildew','Oomycete','Peronospora manshurica','Leaf','A water-mould disease of soybean leaves, pods and seed.','Spores survive in residue and on seed; cool, humid weather lets them infect.','Usually minor; seed can be infected.','Heavy infection causes early leaf drop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('soybean','frogeye_leaf_spot','Frogeye Leaf Spot','Fungal','Cercospora sojina','Leaf','A fungal leaf spot of soybean with round, grey spots ringed in red-purple.','Spores survive on residue and seed; warm, humid weather spreads them by wind and rain.','Spots reduce the leaf area; leaves can drop.','Severe infection reduces yield; fungicide resistance is common.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('soybean','mosaic','Soybean Mosaic','Viral','Soybean mosaic virus (SMV, a potyvirus)','Leaf','A virus disease that mottles and puckers soybean leaves and mottles the seed.','Spread in infected seed and by aphids that pick it up from infected plants within seconds.','Yield and seed quality fall.','Infected seed carries it into the next crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('squash','powdery_mildew','Powdery Mildew','Fungal',NULL,'Leaf','A fungal disease (Podosphaera xanthii and others) of squash, pumpkin, cucumber and melon.','Warm days, dense plants and shade; spores blow in on the wind and do not need wet leaves.','Leaves die early, which cuts yield and fruit quality.','Plants can lose most of their leaves late in the season.',3.499999940395355224e-01,0.699999988079071,1.1999999731779098511e-01,7.999999821186065673e-02);
INSERT INTO "diseases" VALUES('squash','bacterial_wilt','Bacterial Wilt','Bacterial','Erwinia tracheiphila','WholePlant','A bacterial disease that blocks the water vessels of squash and cucumber, so the plant wilts and dies.','Striped and spotted cucumber beetles carry the bacteria in their gut and infect plants as they feed.','Wilted plants die within one to two weeks.','Beetles keep spreading the bacteria to the rest of the planting.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('squash','downy_mildew','Downy Mildew','Oomycete','Pseudoperonospora cubensis','Leaf','A water-mould disease of cucurbit leaves that spreads fast in humid weather.','Spores blow in on the wind from infected crops further south; leaf wetness and humid nights let them infect.','Leaves die quickly, so fruit is exposed and poorly filled.','An unchecked epidemic can kill the leaves of a whole field within weeks.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('squash','yellow_mosaic_virus','Zucchini Yellow Mosaic','Viral','Zucchini yellow mosaic virus (ZYMV, a potyvirus)','Leaf','A virus disease of squash and other cucurbits that mottles and deforms the leaves and fruit.','Aphids pick up the virus while probing infected plants and pass it on within minutes.','Infected plants grow little and their fruit cannot be sold.','Early infection can wipe out a planting.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('strawberry','leaf_scorch','Leaf Scorch','Fungal',NULL,'Leaf','A fungal disease (Diplocarpon earlianum) of strawberry leaves, stalks and runners.','Wet weather and long leaf wetness; the fungus survives on old infected leaves.','Leaves die back, weakening the plant.','Heavily infected plants yield less and survive the winter poorly.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('strawberry','anthracnose','Anthracnose Fruit Rot','Fungal','Colletotrichum acutatum (and related species)','Fruit','A fungal disease of strawberry that rots the fruit and can attack runners and crowns.','Spores come in on infected transplants and spread by rain splash and overhead watering in warm weather.','Infected fruit is lost, sometimes most of a picking.','The fungus builds up in the planting and on mummies.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('banana','anthracnose','Anthracnose','Fungal','Colletotrichum musae','Fruit','A fungal rot of ripening banana fruit, mostly after harvest.','Spores from dead leaves and flower remains infect green fruit through wounds; the rot appears as the fruit ripens.','Fruit spoils quickly in ripening and storage.','Losses rise with bruising and warm storage.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('banana','black_leaf_streak','Black Leaf Streak (Black Sigatoka)','Fungal','Pseudocercospora fijiensis','Leaf','The most damaging leaf disease of banana: streaks that merge and kill large areas of leaf.','Wind and rain spread spores from infected leaves; frequent rain and high humidity favour it.','Plants lose leaves before the bunch fills; fruit is small and ripens early.','Yield losses of 30-50% or more where it is not controlled.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('banana','bunchy_top','Banana Bunchy Top','Viral','Banana bunchy top virus (BBTV, a babuvirus)','WholePlant','A virus disease that stunts banana plants into a bunched rosette of narrow, upright leaves.','The banana aphid (Pentalonia nigronervosa) carries the virus; infected suckers and planting material carry it farther.','Infected plants produce little or no fruit.','Without removal, the virus spreads through the plantation.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('banana','cigar_end_rot','Cigar End Rot','Fungal','Trachysphaera fructigena and Verticillium theobromae','Fruit','A fungal rot that turns the flower end of banana fingers dry and ashen, like the burnt end of a cigar.','Spores infect the dying flower parts at the finger tips in wet weather, and the rot spreads into the fruit.','Affected fingers are unsaleable.','Many fingers of a bunch can be affected in wet seasons.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('banana','cordana_leaf_spot','Cordana Leaf Spot','Fungal','Neocordana musae (syn. Cordana musae)','Leaf','A fungal leaf spot of banana with large, pale, oval spots ringed in yellow.','Spores spread by wind and rain from infected leaves; it often follows other leaf diseases and wounds.','Reduces healthy leaf area; usually less damaging than Sigatoka.','Many spots combine with other diseases to kill leaves early.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('banana','panama_disease','Panama Disease (Fusarium Wilt)','Fungal','Fusarium oxysporum f. sp. cubense (incl. Tropical Race 4)','WholePlant','A soil-borne fungal wilt that blocks the water vessels of banana plants; Tropical Race 4 also kills Cavendish.','The fungus lives in the soil for decades and enters through the roots; it spreads in soil on boots, tools, vehicles, water and infected planting material.','Infected plants die without a bunch.','The soil stays infested for decades; the disease spreads field to field.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('basil','downy_mildew','Basil Downy Mildew','Oomycete','Peronospora belbahrii','Leaf','A water-mould disease that yellows basil leaves and covers their undersides with grey-purple spores.','Spores come in on infected seed and transplants and blow in on the wind; warm, humid nights with wet leaves let them infect.','Leaves are unsaleable; plants can be lost within days.','The whole planting can be lost in humid weather.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('bean','halo_blight','Halo Blight','Bacterial','Pseudomonas savastanoi pv. phaseolicola','Leaf','A bacterial disease of beans with small brown spots inside wide yellow-green halos.','The bacteria come in on infected seed and spread by rain splash, wind and handling in cool, wet weather.','Leaves and pods are spotted; yield and seed quality fall.','Infected seed carries it into the next crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('bean','mosaic_virus','Bean Common Mosaic','Viral','Bean common mosaic virus (BCMV, a potyvirus)','Leaf','A virus disease that mottles and curls bean leaves.','Carried in seed and spread by aphids that probe infected plants.','Yield falls.','Infected seed spreads it to the next crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('bean','rust','Bean Rust','Fungal','Uromyces appendiculatus','Leaf','A rust fungus of bean leaves.','Spores blow in on the wind or survive on old bean debris; leaves wet for 10+ hours in mild weather get infected.','Leaf loss reduces pod fill.','Severe early rust can cut yield substantially.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('broccoli','alternaria_leaf_spot','Alternaria Leaf Spot','Fungal','Alternaria brassicicola and A. brassicae','Leaf','A fungal leaf spot of broccoli and other brassicas with dark, target-like spots.','Spores survive on brassica debris and seed and spread by wind and rain in warm, wet weather.','Spotted outer leaves and blemished heads reduce quality.','Severe spotting reaches the harvested part.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('broccoli','downy_mildew','Downy Mildew','Oomycete','Hyaloperonospora brassicae','Leaf','A water-mould disease of broccoli and other brassicas, worst in cool, damp weather.','Spores spread by wind and splash from infected plants and debris; cool nights with leaf wetness let them infect.','Spotted leaves and heads lose quality.','Seedlings can be killed.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('broccoli','ring_spot','Ring Spot','Fungal','Mycosphaerella brassicicola','Leaf','A fungal leaf spot of brassicas with grey spots full of tiny black dots in rings.','Spores from brassica debris spread by wind and rain in cool, wet weather.','Outer leaves die early; spots can mark the harvested part.','Heavy spotting lowers yield and quality.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cabbage','alternaria_leaf_spot','Alternaria Leaf Spot','Fungal','Alternaria brassicicola and A. brassicae','Leaf','A fungal leaf spot of cabbage and other brassicas with dark, target-like spots.','Spores survive on brassica debris and seed and spread by wind and rain in warm, wet weather.','Spotted outer leaves and blemished heads reduce quality.','Severe spotting reaches the harvested part.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cabbage','black_rot','Black Rot','Bacterial','Xanthomonas campestris pv. campestris','Leaf','The most serious bacterial disease of cabbage and other brassicas: V-shaped yellow lesions from the leaf edge with blackened veins.','Bacteria come in on seed and transplants and spread by rain splash, tools and insects; they enter through the pores at the leaf edge.','Leaves die and heads are stunted and rot.','Whole plantings can be lost in warm, wet seasons.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cabbage','downy_mildew','Downy Mildew','Oomycete','Hyaloperonospora brassicae','Leaf','A water-mould disease of cabbage and other brassicas, worst in cool, damp weather.','Spores spread by wind and splash from infected plants and debris; cool nights with leaf wetness let them infect.','Spotted leaves and heads lose quality.','Seedlings can be killed.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('carrot','alternaria_leaf_blight','Alternaria Leaf Blight','Fungal','Alternaria dauci','Leaf','A fungal blight of carrot leaves, starting on the older leaves.','Spores survive on carrot debris and seed and spread by wind and rain in warm, wet weather.','Weak tops break when harvesting by machine; roots stay small.','Severe blight kills the foliage and cuts yield.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('carrot','cavity_spot','Cavity Spot','Oomycete','Pythium violae and P. sulcatum','Root','A soil-borne disease that pits the carrot root with small sunken lesions.','Pythium water moulds in the soil infect the root, especially in wet, compacted soils; it builds up with frequent carrot crops.','Pitted roots cannot be sold fresh.','Losses grow the longer roots stay in the ground.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('carrot','cercospora_leaf_blight','Cercospora Leaf Blight','Fungal','Cercospora carotae','Leaf','A fungal leaf blight of carrot, often on younger leaves and leaf edges.','Spores survive on debris and seed and spread by wind and splash in warm, humid weather.','Leaf loss weakens the tops.','Yield falls when foliage dies early.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cauliflower','alternaria_leaf_spot','Alternaria Leaf Spot','Fungal','Alternaria brassicicola and A. brassicae','Leaf','A fungal leaf spot of cauliflower and other brassicas with dark, target-like spots.','Spores survive on brassica debris and seed and spread by wind and rain in warm, wet weather.','Spotted outer leaves and blemished heads reduce quality.','Severe spotting reaches the harvested part.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cauliflower','bacterial_soft_rot','Bacterial Soft Rot','Bacterial','Pectobacterium carotovorum (and related species)','Head','A bacterial rot that turns parts of the cauliflower curd soft, slimy and foul-smelling.','Soil bacteria enter the curd through wounds, insect damage and frost cracks, especially when water sits on the head in warm weather.','Rotted heads are lost, in the field and in storage.','The rot spreads to neighbouring heads in wet weather.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('celery','anthracnose','Anthracnose (Leaf Curl)','Fungal','Colletotrichum acutatum (C. fioriniae)','Leaf','A fungal disease that curls celery leaves and cracks the leaf stalks.','Spores spread by rain splash and overhead irrigation in warm, wet weather; they come in on transplants and weeds.','Twisted, cracked stalks are unsaleable.','Whole plantings can be lost in warm, wet summers.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('celery','early_blight','Early Blight','Fungal','Cercospora apii','Leaf','Cercospora early blight: a fungal leaf spot of celery in warm, humid weather.','Spores survive on debris and seed and spread by wind and splash; warm, humid weather with dew favours it.','Spotted leaves and stalks lower quality and yield.','Severe blight destroys the leaves.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('chilli','leaf_curl','Chilli Leaf Curl','Viral','Chilli leaf curl virus and other begomoviruses','Leaf','The most damaging virus disease of chilli: leaves curl, pucker and shrink, and the plant stops growing.','Whiteflies (Bemisia tabaci) carry the virus from infected plants and weeds as they feed.','Infected plants yield little.','Early infection can make a whole planting worthless.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('chilli','anthracnose','Anthracnose (Fruit Rot)','Fungal','Colletotrichum capsici and C. gloeosporioides','Fruit','A fungal rot of chilli fruit, also called die back when it kills the shoot tips.','Spores come in on seed and debris and spread by rain splash in warm, wet weather, mostly on ripening fruit.','Rotting fruit is lost before and after harvest.','Can destroy much of a crop in wet seasons.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('chilli','leaf_spot','Cercospora Leaf Spot','Fungal','Cercospora capsici','Leaf','A fungal leaf spot of chilli with pale-centred, dark-ringed ''frog-eye'' spots.','Spores survive on debris and seed and spread by wind and rain in warm, humid weather.','Leaf drop exposes fruit to sunscald and cuts yield.','Severe spotting defoliates plants.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('chilli','powdery_mildew','Powdery Mildew','Fungal','Leveillula taurica','Leaf','A powdery mildew that grows inside chilli leaves: white powder underneath, yellow patches on top.','Spores blow on the wind; warm days, cool nights and dry leaves favour it.','Heavy leaf drop cuts yield and causes sunscald.','Severe attacks defoliate plants.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('chilli','whitefly','Whitefly','Pest','Bemisia tabaci (silverleaf whitefly)','Leaf','Tiny white sap-sucking insects under chilli leaves; they also spread leaf curl virus.','Whiteflies breed fast in warm, dry weather and fly between crops and weeds.','Feeding weakens plants; honeydew and sooty mould soil the leaves.','They spread leaf curl virus, which is worse than the feeding.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('coffee','berry_blotch','Berry Blotch','Fungal','Cercospora coffeicola','Fruit','The berry phase of brown eye spot: dark, sunken blotches on coffee cherries.','Spores spread by wind and rain; stressed, poorly fed bushes in full sun are most affected.','Berries lose quality and the beans can be damaged.','Losses rise on stressed, under-fed bushes.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('coffee','black_rot','Black Rot (Koleroga)','Fungal','Ceratobasidium noxium (syn. Corticium koleroga)','Leaf','A fungal disease of coffee in very wet, shaded plantations: leaves blacken and hang from the branches on fungal threads.','Spreads in long rainy spells under heavy shade; fungal threads grow along the twigs from infected leaves.','Branches lose their leaves and berries.','Severe in monsoon areas with heavy shade.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('coffee','brown_eye_spot','Brown Eye Spot','Fungal','Cercospora coffeicola','Leaf','A fungal leaf spot of coffee with round brown spots and pale centres, like eyes.','Spores spread by wind and rain; worse on stressed, under-fed bushes and seedlings in full sun.','Leaf loss weakens the bush.','Seedlings in nurseries can be badly affected.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('coffee','leaf_rust','Coffee Leaf Rust','Fungal','Hemileia vastatrix','Leaf','The most important disease of Arabica coffee: orange powdery rust under the leaves and heavy leaf loss.','Spores spread by wind, rain and people; they need liquid water on the leaf to infect, at 21-25 °C.','Leaf loss cuts the next year''s crop.','Severe epidemics have devastated coffee regions.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cotton','bacterial_blight','Bacterial Blight (Angular Leaf Spot)','Bacterial','Xanthomonas citri pv. malvacearum','Leaf','A bacterial disease of cotton that spots the leaves, blackens the stems (''black arm'') and rots the bolls.','The bacteria come in on seed and crop debris and spread by wind-driven rain, splash and overhead irrigation in warm, humid weather.','Leaf loss and boll rot reduce yield and lint quality.','In wet seasons it defoliates plants and rots many bolls.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cotton','leaf_curl_virus','Cotton Leaf Curl Disease','Viral','Cotton leaf curl virus complex (begomoviruses with betasatellite)','Leaf','A whitefly-borne virus disease of cotton in South Asia and Africa: leaves curl, veins thicken and plants are stunted.','Whiteflies (Bemisia tabaci) carry the virus from infected cotton, weeds and other hosts as they feed.','Infected plants set few bolls.','Early infection can make a whole field uneconomic.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cotton','fusarium_wilt','Fusarium Wilt','Fungal','Fusarium oxysporum f. sp. vasinfectum','WholePlant','A soil-borne fungal wilt of cotton that blocks the water vessels; worst in sandy soils with root-knot nematodes.','The fungus lives in the soil for years and enters through the roots, often through nematode wounds; it spreads in soil, water and seed.','Plants are stunted and lose their leaves and bolls.','Seedlings and young plants die; the soil stays infested for years.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cucumber','angular_leaf_spot','Angular Leaf Spot','Bacterial','Pseudomonas syringae pv. lachrymans','Leaf','A bacterial leaf spot of cucumber with angular, vein-bounded spots that tear out.','Bacteria come in on seed and spread by rain splash, handling and insects in warm, wet weather.','Leaves are ragged; fruit can be spotted and rot.','Heavy infection defoliates plants.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cucumber','bacterial_wilt','Bacterial Wilt','Bacterial','Erwinia tracheiphila','WholePlant','A bacterial disease that blocks the water vessels of cucumber, so the vines wilt and die.','Striped and spotted cucumber beetles carry the bacteria in their gut and infect plants as they feed.','Wilted plants die within one to two weeks.','Beetles keep spreading the bacteria to the rest of the planting.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('cucumber','powdery_mildew','Powdery Mildew','Fungal','Podosphaera xanthii (and Golovinomyces orontii)','Leaf','A fungal disease that coats cucumber leaves with white powder.','Spores blow in on the wind; warm days, shade and dense plants favour it, and the leaves need not be wet.','Fewer leaves means smaller, poorer fruit.','Plants decline early.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('eggplant','cercospora_leaf_spot','Cercospora Leaf Spot','Fungal','Cercospora melongenae','Leaf','A fungal leaf spot of eggplant with angular, yellow-edged spots.','Spores survive on debris and spread by wind and rain in warm, humid weather.','Leaf loss lowers yield and exposes fruit to sun.','Severe spotting defoliates plants.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('eggplant','phomopsis_fruit_rot','Phomopsis Blight and Fruit Rot','Fungal','Diaporthe vexans (syn. Phomopsis vexans)','Fruit','A fungal disease of eggplant that rots the fruit and spots the leaves and stems.','Spores come in on seed and debris and spread by rain splash in hot, wet weather.','Rotting fruit is lost, in the field and after harvest.','Can destroy a large part of the crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('eggplant','phytophthora_blight','Phytophthora Blight','Oomycete','Phytophthora capsici','Fruit','A water-mould disease that rots eggplant fruit and can collapse whole plants.','The water mould lives in the soil and spreads in water: rain splash, standing water and irrigation; worst on poorly drained soil.','Fruit rots and plants can be killed.','Infested fields stay infested for years.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('garlic','leaf_blight','Leaf Blight','Fungal','Stemphylium vesicarium (often with Alternaria porri, purple blotch)','Leaf','A fungal blight of garlic leaves that starts on the leaf tips and on damaged tissue.','Spores survive on debris and spread by wind in warm, humid weather; leaves damaged by thrips, hail or sun are infected first.','Leaves die early, so bulbs stay small.','Severe blight cuts yield and storage quality.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('garlic','rust','Garlic Rust','Fungal','Puccinia allii','Leaf','A rust fungus of garlic and leek leaves.','Spores blow in or survive on infected allium plants; moderate temperatures with dew favour it.','Bulbs stay small and store poorly.','Severe rust can halve the yield.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('ginger','leaf_spot','Leaf Spot','Fungal','Phyllosticta zingiberis','Leaf','A fungal leaf spot of ginger in the rainy season.','Spores spread by rain splash from infected leaves; frequent rain and humidity favour it.','Leaf loss reduces rhizome growth.','Severe outbreaks cut yield.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('ginger','sheath_blight','Sheath Blight','Fungal','Rhizoctonia solani','Leaf','A soil-borne fungal blight of the leaf sheaths and leaves of ginger.','The fungus lives in the soil and infects the lower sheaths in warm, humid weather, especially in dense, wet plantings.','Shoots die back, reducing rhizome yield.','Spreads through dense, wet plantings.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('lettuce','downy_mildew','Downy Mildew','Oomycete','Bremia lactucae','Leaf','The most important leaf disease of lettuce: pale, angular patches with white spores underneath.','Spores spread by wind; cool, moist weather with long leaf wetness lets them infect.','Spotted leaves must be trimmed; heads may be unsaleable.','Rots can follow in storage.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('lettuce','mosaic_virus','Lettuce Mosaic','Viral','Lettuce mosaic virus (LMV, a potyvirus)','Leaf','A virus disease that mottles and distorts lettuce and stops heads forming.','Carried in seed and spread by aphids from infected plants.','Plants are unsaleable.','Infected seed spreads it to new plantings.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('mango','anthracnose','Anthracnose','Fungal','Colletotrichum gloeosporioides (and related species)','Leaf','The most important disease of mango: dark spots on young leaves, blackened flowers and rotting fruit.','Spores from infected leaves, twigs and old flower stalks spread by rain splash; wet weather at flushing and flowering favours it.','Leaf spotting, flower loss and fruit rot reduce the crop.','Repeated years of blossom blight can cut yields heavily.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('mango','bacterial_canker','Bacterial Canker (Black Spot)','Bacterial','Xanthomonas citri pv. mangiferaeindicae','Leaf','A bacterial disease of mango leaves, twigs and fruit with raised, angular black spots.','Bacteria survive in leaf and twig lesions and spread by wind-driven rain, especially through wounds.','Spotted leaves drop; fruit is blemished and may rot.','Severe outbreaks defoliate trees and spoil most fruit.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('mango','cutting_weevil','Leaf-Cutting Weevil','Pest','Deporaus marginatus (mango leaf-cutting weevil)','Leaf','A small weevil that lays eggs in young mango leaves and then cuts the leaves off near their base.','Adult weevils are active on new, tender flushes; the females cut the leaves so the egg-bearing pieces fall to the ground.','New flushes lose their leaves, delaying growth.','Young trees in nurseries can be stripped of new leaves.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('mango','die_back','Die Back','Fungal','Lasiodiplodia theobromae','Leaf','A fungal disease that kills mango twigs and branches from the tip downward.','The fungus enters through wounds and stressed tissue; drought, sun scald and damage favour it.','Branches die and the crown thins.','Severe die back can kill large limbs or young trees.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('mango','gall_midge','Gall Midge','Pest','Procontarinia spp. (mango gall midges)','Leaf','Tiny flies whose larvae form small raised galls on mango leaves.','Midges lay eggs in young leaves; each larva makes a small wart-like gall as it feeds.','Galled leaves photosynthesise less and drop.','Heavy infestations weaken young trees and new flushes.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('mango','powdery_mildew','Powdery Mildew','Fungal','Erysiphe quercicola (syn. Oidium mangiferae)','Leaf','A fungal disease that coats mango flowers, young fruit and leaves with white powder.','Spores blow on the wind; cool nights and dry, mild days at flowering favour it.','Flowers and young fruit drop, so the crop is small.','Severe attacks at flowering can wipe out the crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('mango','sooty_mould','Sooty Mould','Fungal','Capnodium and related sooty moulds (growing on insect honeydew)','Leaf','A black, soot-like coating of fungi growing on the honeydew of sap-sucking insects.','Mango hoppers, scale insects and mealybugs drop sticky honeydew on the leaves; sooty moulds grow on it.','The coating shades the leaves and reduces photosynthesis.','Heavy coating weakens the tree and soils the fruit.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('maple','tar_spot','Tar Spot','Fungal','Rhytisma acerinum','Leaf','A fungal leaf disease of maples that leaves raised black spots like drops of tar.','Spores from last year''s fallen leaves are released in spring and infect the new leaves in wet weather.','Mostly cosmetic; trees are rarely harmed.','Heavy years cause some early leaf fall.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('plum','bacterial_spot','Bacterial Spot','Bacterial','Xanthomonas arboricola pv. pruni','Leaf','A bacterial disease of plum and other stone fruit leaves, twigs and fruit.','Bacteria overwinter in twig cankers and spread by wind-driven rain in warm, wet weather.','Leaves drop early and fruit is blemished.','Repeated defoliation weakens trees.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('plum','brown_rot','Brown Rot','Fungal','Monilinia fructicola (and M. laxa)','Fruit','A fungal disease of stone fruit that blights blossoms and rots the fruit.','Spores from mummified fruit and twig cankers infect blossoms in wet spring weather and ripening fruit near harvest, often through wounds.','Rotted fruit is lost, on the tree and in storage.','Mummies and cankers start next year''s infections.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('plum','pocket_disease','Plum Pocket','Fungal','Taphrina pruni','Fruit','A fungal disease that turns young plums into swollen, hollow, stoneless ''pockets''.','Spores on the bark and buds infect the flowers and young fruit in cool, wet spring weather.','Affected fruit is lost.','Losses can be heavy in wet springs.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('plum','plum_pox_virus','Plum Pox (Sharka)','Viral','Plum pox virus (PPV, a potyvirus)','Leaf','The most serious virus of plum and other stone fruit: pale rings on leaves and fruit, and fruit drops early.','Aphids spread it within an orchard; infected nursery trees and budwood spread it over long distances.','Fruit is unsaleable and falls early.','Infected trees stay infected; it is a quarantine disease in many countries.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('plum','rust','Plum Rust','Fungal','Tranzschelia discolor','Leaf','A rust fungus of plum and other stone fruit leaves.','Spores blow in or survive in twig cankers; long leaf wetness in warm weather lets them infect.','Early leaf fall weakens the tree for next year.','Repeated defoliation reduces vigour and fruit size.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('rice','blast','Rice Blast','Fungal','Pyricularia oryzae (Magnaporthe oryzae)','Leaf','The most damaging disease of rice: diamond-shaped leaf lesions and broken necks of the panicle.','Spores spread by wind; long dew, cool nights and high nitrogen favour it.','Leaf blast kills seedlings; neck blast empties the panicles.','Can destroy most of a crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('rice','sheath_blight','Sheath Blight','Fungal','Rhizoctonia solani','Leaf','A soil-borne fungal disease of rice leaf sheaths, worst in dense, heavily fertilised crops.','Fungal resting bodies float on the flood water and infect the sheaths at the water line; it climbs in warm, humid weather.','Lodging and poor grain fill.','Yield losses in dense, high-nitrogen crops.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('rice','bacterial_leaf_blight','Bacterial Leaf Blight','Bacterial','Xanthomonas oryzae pv. oryzae','Leaf','One of the most serious rice diseases: leaves yellow and dry from the tips and edges.','Bacteria enter through leaf pores and wounds and spread in irrigation water, rain and wind; storms and heavy nitrogen favour it.','Dried leaves cut grain fill; seedlings can wilt (kresek).','Epidemics after storms can halve yields.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('rice','brown_spot','Brown Spot','Fungal','Bipolaris oryzae (Cochliobolus miyabeanus)','Leaf','A fungal leaf spot of rice that is worst in poor, nutrient-short soils; it caused the 1943 Bengal famine.','The fungus comes in on seed and debris; spores spread by wind in warm, humid weather, mostly on stressed, poorly fed rice.','Spotted leaves and grain cut yield and quality.','Severe on poor soils, where it can destroy much of the crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('rice','tungro','Rice Tungro','Viral','Rice tungro bacilliform virus with rice tungro spherical virus','Leaf','A virus disease of rice in South and Southeast Asia: plants are stunted and their leaves turn yellow to orange.','Green leafhoppers (Nephotettix virescens) carry the two viruses from infected rice, stubble regrowth and weeds.','Infected plants yield little.','Early infection over a whole area can lose most of the crop.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('sugarcane','mosaic','Sugarcane Mosaic','Viral','Sugarcane mosaic virus (SCMV) and related potyviruses','Leaf','A virus disease that mottles sugarcane leaves with pale green streaks.','Aphids spread the virus; infected seed cane (setts) carries it into new fields.','Growth and sugar yield fall.','Infected setts carry it into every new planting.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('sugarcane','red_rot','Red Rot','Fungal','Colletotrichum falcatum','Leaf','The most destructive fungal disease of sugarcane: it rots the inside of the cane red and marks the leaf midribs.','Spores spread in infected setts, by rain and irrigation water, and through borer holes; waterlogging and susceptible varieties favour it.','Infected canes dry out and lose their sugar.','Whole fields can be lost with susceptible varieties.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('sugarcane','rust','Sugarcane Rust','Fungal','Puccinia melanocephala (brown rust) and P. kuehnii (orange rust)','Leaf','Rust fungi that streak sugarcane leaves with brown or orange pustules.','Spores blow on the wind; warm, humid weather with dew favours infection.','Leaf area falls, reducing growth and sugar.','Severe rust can cut yields of susceptible varieties sharply.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('sugarcane','yellow_leaf','Yellow Leaf Disease','Viral','Sugarcane yellow leaf virus (SCYLV, a polerovirus)','Leaf','A virus disease that yellows the midrib of sugarcane leaves and stunts the canes.','Aphids (the sugarcane aphid) spread the virus; infected seed cane carries it to new fields.','Cane and sugar yields fall.','Losses grow in ratoon crops.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('tobacco','blue_mold','Blue Mold','Oomycete','Peronospora tabacina','Leaf','A water-mould disease of tobacco leaves that can spread rapidly through a region.','Spores blow long distances on the wind; cool, wet, cloudy weather favours infection.','Leaves are destroyed; seedbeds can be wiped out.','Regional epidemics can ruin crops.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('tobacco','brown_spot','Brown Spot','Fungal','Alternaria alternata','Leaf','A fungal leaf spot of mature tobacco leaves with ringed brown spots.','Spores survive on debris and spread by wind; mature, lower leaves in warm, wet weather are infected.','Leaf quality falls.','Heavy losses in warm, wet seasons.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('tobacco','frogeye_leaf_spot','Frogeye Leaf Spot','Fungal','Cercospora nicotianae','Leaf','A fungal leaf spot of tobacco with small white-centred spots.','Spores spread by wind and rain from debris and infected leaves in warm, humid weather.','Spotted leaves lose value.','Heavy spotting cuts yield and quality.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('tobacco','mosaic_virus','Tobacco Mosaic','Viral','Tobacco mosaic virus (TMV, a tobamovirus)','Leaf','A very stable, contagious virus that mottles and distorts tobacco leaves.','Spreads by contact: hands, tools and clothing; it survives for years in debris and dried leaf. No insect is needed.','Yield and leaf quality fall.','Every handling spreads it along the row.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','bacterial_leaf_streak','Bacterial Leaf Streak (Black Chaff)','Bacterial','Xanthomonas translucens pv. undulosa','Leaf','A bacterial disease of wheat that streaks the leaves and blackens the glumes of the head.','Bacteria come in on seed and spread by rain and wind in warm, wet weather.','Leaf area and grain fill fall.','No chemical control works well.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','head_scab','Fusarium Head Blight (Scab)','Fungal','Fusarium graminearum (and other Fusarium spp.)','Head','A fungal disease of wheat heads that bleaches spikelets and contaminates grain with mycotoxins.','Spores from maize and wheat residue infect the heads at flowering in warm, wet weather.','Yield falls and grain may contain mycotoxins (DON).','Contaminated grain can be rejected.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','leaf_rust','Leaf Rust (Brown Rust)','Fungal','Puccinia triticina','Leaf','A rust fungus of wheat leaves with scattered orange-brown pustules.','Spores blow long distances on the wind; dew on the leaves lets them infect, and new spores form within one to two weeks.','Rusted leaves lose their green area, so grain fill suffers.','Severe epidemics can cut yield heavily.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','loose_smut','Loose Smut','Fungal','Ustilago tritici','Head','A seed-borne fungal disease that replaces the wheat head with a mass of black spores.','The fungus lives inside the seed embryo; infected seed grows into plants whose heads are spore masses that infect neighbouring flowers.','Infected heads produce no grain.','Spores infect neighbouring flowers, so next year''s seed is infected.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','powdery_mildew','Powdery Mildew','Fungal','Blumeria graminis f. sp. tritici','Leaf','A fungal disease that covers wheat leaves with white, fluffy powder.','Spores blow on the wind; cool to mild, humid weather and dense, lush crops favour it; the leaves need not be wet.','Leaf area falls, reducing grain fill.','Heavy early mildew cuts yield.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','septoria_blotch','Septoria Tritici Blotch','Fungal','Zymoseptoria tritici','Leaf','The most common leaf disease of wheat in wet climates: long brown blotches dotted with black spore bodies.','Spores from residue and the lower leaves are splashed upward by rain.','Upper leaves die early and grain fill falls.','Yield losses in wet seasons.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','stem_rust','Stem Rust (Black Rust)','Fungal','Puccinia graminis f. sp. tritici','Leaf','A rust fungus of wheat stems and leaves; strains such as Ug99 can destroy crops.','Spores blow long distances on the wind; dew on the leaves lets them infect, and new spores form within one to two weeks.','Rusted leaves lose their green area, so grain fill suffers.','Severe epidemics can cut yield heavily.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','stripe_rust','Stripe Rust (Yellow Rust)','Fungal','Puccinia striiformis f. sp. tritici','Leaf','A rust fungus of wheat that forms yellow stripes of pustules along the leaves in cool weather.','Spores blow long distances on the wind; dew on the leaves lets them infect, and new spores form within one to two weeks.','Rusted leaves lose their green area, so grain fill suffers.','Severe epidemics can cut yield heavily.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','leaf_blight','Leaf Blight (Spot Blotch)','Fungal','Bipolaris sorokiniana (Cochliobolus sativus)','Leaf','The main leaf blight of wheat in warm, humid regions such as the plains of South Asia.','The fungus comes in on seed and residue; spores spread by wind and rain in warm, humid weather after heading.','Dried leaves cut grain fill; grain is shrivelled and black-pointed.','Severe in late-sown, warm crops.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
INSERT INTO "diseases" VALUES('wheat','blast','Wheat Blast','Fungal','Magnaporthe oryzae pathotype Triticum','Head','A fast, destructive disease of wheat heads, first seen in Brazil and since 2016 in Bangladesh and Zambia.','Spores spread by wind and on seed; warm, wet weather at heading lets them infect the rachis and kill the head above it.','Bleached heads give little or no grain.','Outbreaks can destroy whole fields within days.',3.499999940395355224e-01,0.699999988079071,1.5000000596046447754e-01,1.0000000149011611938e-01);
