INSERT INTO "followups" VALUES('tomato','early_blight','new_growth','Inspect the new leaf','The new leaf is clean: no new lesions in this simulation.','If lesions appear on new leaves, repeat sanitation and reassess protection.','treatment_content');
INSERT INTO "followups" VALUES('tomato','early_blight','old_lesions','Inspect the remaining lesions','Old lesions remain on the treated leaf; dead tissue does not recover.','Watch for new lesions near the old ones.','treatment_content');
INSERT INTO "followups" VALUES('tomato','bacterial_spot','new_growth','Inspect the new leaf','The new leaf is largely free of fresh spots.','Replace heavily affected young plants with clean stock.','treatment_content');
INSERT INTO "followups" VALUES('tomato','bacterial_spot','old_lesions','Inspect the remaining lesions','Old lesions remain on the treated leaf; dead tissue does not recover.','Watch for new lesions near the old ones.','treatment_content');
INSERT INTO "followups" VALUES('tomato','late_blight','replacement','Inspect the replacement','The replacement is healthy; the outbreak is contained.','Report new lesions immediately.','treatment_content');
INSERT INTO "followups" VALUES('tomato','leaf_mold','new_growth','Inspect the new leaf','The new leaf has no mould underneath in this simulation.','If mould returns, check humidity and vent operation first.','treatment_content');
INSERT INTO "followups" VALUES('tomato','leaf_mold','old_lesions','Inspect the remaining lesions','Old lesions remain on the treated leaf; dead tissue does not recover.','Watch for new lesions near the old ones.','treatment_content');
INSERT INTO "followups" VALUES('tomato','septoria_leaf_spot','new_growth','Inspect the new leaf','The new upper leaf stays clean in this simulation.','If spots reach upper leaves, reassess protection.','treatment_content');
INSERT INTO "followups" VALUES('tomato','septoria_leaf_spot','old_lesions','Inspect the remaining lesions','Old lesions remain on the treated leaf; dead tissue does not recover.','Watch for new lesions near the old ones.','treatment_content');
INSERT INTO "followups" VALUES('tomato','spider_mites','new_growth','Inspect the new leaf','Few active mites; the new leaf is less damaged.','If mites rebound, reassess the route and conditions.','treatment_content');
INSERT INTO "followups" VALUES('tomato','spider_mites','old_lesions','Inspect the remaining lesions','Old stippling remains.','Watch for new lesions near the old ones.','treatment_content');
INSERT INTO "followups" VALUES('tomato','target_spot','new_growth','Inspect the new leaf','The new leaf is protected; advanced lesions remain on the old one.','Rotate modes of action if spots reappear.','treatment_content');
INSERT INTO "followups" VALUES('tomato','target_spot','old_lesions','Inspect the remaining lesions','Old lesions remain on the treated leaf; dead tissue does not recover.','Watch for new lesions near the old ones.','treatment_content');
INSERT INTO "followups" VALUES('tomato','yellow_leaf_curl_virus','replacement','Inspect the replacement','Healthy replacement established; few whiteflies on the card.','If counts rise, review exclusion.','treatment_content');
INSERT INTO "followups" VALUES('tomato','mosaic_virus','replacement','Inspect the replacement','The replacement shows no mottling.','If symptoms appear, repeat removal and sanitation.','treatment_content');
