INSERT INTO "followups" VALUES('corn','common_rust','old_lesions','Inspect the remaining lesions','Old lesions remain on the treated leaf; dead tissue does not recover.','Watch for new lesions near the old ones.','treatment_content');
INSERT INTO "followups" VALUES('corn','northern_leaf_blight','new_growth','Inspect the new leaf','Healthy tissue stays functional; old lesions remain.','Consult an adviser if lesions reach the ear leaf early.','treatment_content');
INSERT INTO "followups" VALUES('corn','northern_leaf_blight','old_lesions','Inspect the remaining lesions','Old lesions remain on the treated leaf; dead tissue does not recover.','Watch for new lesions near the old ones.','treatment_content');
