INSERT INTO "lifecycle_stages" VALUES('tomato','early_blight',10,'Spores survive on crop debris and in the soil between seasons.');
INSERT INTO "lifecycle_stages" VALUES('tomato','early_blight',20,'Wind and splashing water carry them to the lower, older leaves.');
INSERT INTO "lifecycle_stages" VALUES('tomato','early_blight',30,'Dark spots with rings and yellow halos appear within days in warm, damp weather.');
INSERT INTO "lifecycle_stages" VALUES('tomato','early_blight',40,'Spots join, leaves yellow and drop, and new spores spread to nearby plants.');
INSERT INTO "lifecycle_stages" VALUES('tomato','late_blight',10,'Spores arrive on the wind or from infected tubers and volunteer plants.');
INSERT INTO "lifecycle_stages" VALUES('tomato','late_blight',20,'In cool, wet weather they land on leaves and infect within hours.');
INSERT INTO "lifecycle_stages" VALUES('tomato','late_blight',30,'Greasy grey-green blotches appear and may grow white fuzz underneath.');
INSERT INTO "lifecycle_stages" VALUES('tomato','late_blight',40,'The tissue collapses and releases more spores, so it can spread through a crop in days.');
INSERT INTO "lifecycle_stages" VALUES('tomato','bacterial_spot',10,'The bacteria survive on seed, debris and volunteer plants.');
INSERT INTO "lifecycle_stages" VALUES('tomato','bacterial_spot',20,'Rain splash and wet hands carry them onto leaves.');
INSERT INTO "lifecycle_stages" VALUES('tomato','bacterial_spot',30,'Small water-soaked spots turn dark with yellow halos.');
INSERT INTO "lifecycle_stages" VALUES('tomato','bacterial_spot',40,'Spots join, leaves drop, and fruit gets scabby spots.');
INSERT INTO "lifecycle_stages" VALUES('tomato','leaf_mold',10,'Spores survive on debris and greenhouse surfaces.');
INSERT INTO "lifecycle_stages" VALUES('tomato','leaf_mold',20,'In very humid air they infect the leaf undersides.');
INSERT INTO "lifecycle_stages" VALUES('tomato','leaf_mold',30,'Pale patches show on top, olive mould underneath.');
INSERT INTO "lifecycle_stages" VALUES('tomato','leaf_mold',40,'Leaves wither and the mould releases more spores.');
INSERT INTO "lifecycle_stages" VALUES('tomato','septoria_leaf_spot',10,'The fungus survives on old tomato debris and some weeds.');
INSERT INTO "lifecycle_stages" VALUES('tomato','septoria_leaf_spot',20,'Rain splashes spores onto the lowest leaves.');
INSERT INTO "lifecycle_stages" VALUES('tomato','septoria_leaf_spot',30,'Many small spots with grey centres and black dots appear.');
INSERT INTO "lifecycle_stages" VALUES('tomato','septoria_leaf_spot',40,'Leaves yellow and drop from the bottom up.');
INSERT INTO "lifecycle_stages" VALUES('tomato','spider_mites',10,'Mites overwinter on weeds and sheltered plants.');
INSERT INTO "lifecycle_stages" VALUES('tomato','spider_mites',20,'In hot, dry weather they move onto crops.');
INSERT INTO "lifecycle_stages" VALUES('tomato','spider_mites',30,'They feed under the leaves, leaving pale dots.');
INSERT INTO "lifecycle_stages" VALUES('tomato','spider_mites',40,'Numbers explode in days; leaves bronze and webbing appears.');
INSERT INTO "lifecycle_stages" VALUES('tomato','target_spot',10,'The fungus survives on crop debris.');
INSERT INTO "lifecycle_stages" VALUES('tomato','target_spot',20,'Spores land on leaves wet for many hours.');
INSERT INTO "lifecycle_stages" VALUES('tomato','target_spot',30,'Brown spots with concentric rings appear.');
INSERT INTO "lifecycle_stages" VALUES('tomato','target_spot',40,'Spots merge and leaves drop.');
INSERT INTO "lifecycle_stages" VALUES('tomato','yellow_leaf_curl_virus',10,'Whiteflies pick up the virus from infected plants.');
INSERT INTO "lifecycle_stages" VALUES('tomato','yellow_leaf_curl_virus',20,'They carry it to healthy plants as they feed.');
INSERT INTO "lifecycle_stages" VALUES('tomato','yellow_leaf_curl_virus',30,'New leaves come out small, curled and yellow-edged.');
INSERT INTO "lifecycle_stages" VALUES('tomato','yellow_leaf_curl_virus',40,'The plant stops growing and sets little fruit.');
INSERT INTO "lifecycle_stages" VALUES('tomato','mosaic_virus',10,'The virus survives in seed and plant debris for a long time.');
INSERT INTO "lifecycle_stages" VALUES('tomato','mosaic_virus',20,'It spreads on hands, tools and clothing.');
INSERT INTO "lifecycle_stages" VALUES('tomato','mosaic_virus',30,'Leaves show a light and dark green mosaic and may distort.');
INSERT INTO "lifecycle_stages" VALUES('tomato','mosaic_virus',40,'Every handling can carry it to the next plant.');
INSERT INTO "lifecycle_stages" VALUES('potato','early_blight',10,'Spores survive on crop debris and in the soil between seasons.');
INSERT INTO "lifecycle_stages" VALUES('potato','early_blight',20,'Wind and splashing water carry them to the lower, older leaves.');
INSERT INTO "lifecycle_stages" VALUES('potato','early_blight',30,'Dark spots with rings and yellow halos appear within days in warm, damp weather.');
INSERT INTO "lifecycle_stages" VALUES('potato','early_blight',40,'Spots join, leaves yellow and drop, and new spores spread to nearby plants.');
INSERT INTO "lifecycle_stages" VALUES('potato','late_blight',10,'Spores arrive on the wind or from infected tubers and volunteer plants.');
INSERT INTO "lifecycle_stages" VALUES('potato','late_blight',20,'In cool, wet weather they land on leaves and infect within hours.');
INSERT INTO "lifecycle_stages" VALUES('potato','late_blight',30,'Greasy grey-green blotches appear and may grow white fuzz underneath.');
INSERT INTO "lifecycle_stages" VALUES('potato','late_blight',40,'The tissue collapses and releases more spores, so it can spread through a crop in days.');
INSERT INTO "lifecycle_stages" VALUES('pepper','bacterial_spot',10,'The bacteria survive on seed, plant debris and some weeds between crops.');
INSERT INTO "lifecycle_stages" VALUES('pepper','bacterial_spot',20,'Rain splash and handling wet plants carry them onto leaves, where they enter through tiny openings.');
INSERT INTO "lifecycle_stages" VALUES('pepper','bacterial_spot',30,'Small water-soaked spots turn brown with yellow edges, often angular between the veins.');
INSERT INTO "lifecycle_stages" VALUES('pepper','bacterial_spot',40,'Spots join, leaves yellow and drop, and the bacteria can reach the fruit.');
INSERT INTO "lifecycle_stages" VALUES('pepper','powdery_mildew',10,'The fungus survives on crop remains and on nearby host plants.');
INSERT INTO "lifecycle_stages" VALUES('pepper','powdery_mildew',20,'Wind-blown spores land on leaves; unlike many fungi they do not need wet leaves.');
INSERT INTO "lifecycle_stages" VALUES('pepper','powdery_mildew',30,'Pale yellow patches show on the upper side, with white powdery growth underneath.');
INSERT INTO "lifecycle_stages" VALUES('pepper','powdery_mildew',40,'Leaves curl and drop, which can expose the fruit to sunburn.');
INSERT INTO "lifecycle_stages" VALUES('pepper','blossom_end_rot',10,'Fruit grows fast in warm weather.');
INSERT INTO "lifecycle_stages" VALUES('pepper','blossom_end_rot',20,'Uneven water slows calcium reaching its far end.');
INSERT INTO "lifecycle_stages" VALUES('pepper','blossom_end_rot',30,'Cells there die: a water-soaked patch appears.');
INSERT INTO "lifecycle_stages" VALUES('pepper','blossom_end_rot',40,'The patch sinks and turns dark and leathery.');
INSERT INTO "lifecycle_stages" VALUES('pepper','frogeye_leaf_spot',10,'The fungus survives on debris and seed.');
INSERT INTO "lifecycle_stages" VALUES('pepper','frogeye_leaf_spot',20,'Wind and splash carry spores to leaves.');
INSERT INTO "lifecycle_stages" VALUES('pepper','frogeye_leaf_spot',30,'Grey-centred spots with dark rings form.');
INSERT INTO "lifecycle_stages" VALUES('pepper','frogeye_leaf_spot',40,'Leaves drop and spores spread.');
INSERT INTO "lifecycle_stages" VALUES('apple','apple_scab',10,'The fungus spends winter in fallen, infected leaves.');
INSERT INTO "lifecycle_stages" VALUES('apple','apple_scab',20,'In spring, rain releases spores that land on young leaves and fruit.');
INSERT INTO "lifecycle_stages" VALUES('apple','apple_scab',30,'Olive-green to brown velvety spots appear and later turn dark and scabby.');
INSERT INTO "lifecycle_stages" VALUES('apple','apple_scab',40,'Infected leaves and fruit drop, and the fungus returns to the leaf litter.');
INSERT INTO "lifecycle_stages" VALUES('apple','cedar_apple_rust',10,'The fungus lives on nearby junipers or cedars, forming brown galls.');
INSERT INTO "lifecycle_stages" VALUES('apple','cedar_apple_rust',20,'In spring rain the galls swell into orange, jelly-like horns that release spores.');
INSERT INTO "lifecycle_stages" VALUES('apple','cedar_apple_rust',30,'Bright yellow-orange spots form on apple leaves in early summer.');
INSERT INTO "lifecycle_stages" VALUES('apple','cedar_apple_rust',40,'Late-summer spores return to the junipers: the cycle needs both plants.');
INSERT INTO "lifecycle_stages" VALUES('apple','black_rot',10,'The fungus lives in cankers, dead wood and mummified fruit.');
INSERT INTO "lifecycle_stages" VALUES('apple','black_rot',20,'Spores are released in warm, wet weather.');
INSERT INTO "lifecycle_stages" VALUES('apple','black_rot',30,'Leaves get brown spots with purple borders.');
INSERT INTO "lifecycle_stages" VALUES('apple','black_rot',40,'Fruit rots and mummifies, carrying the fungus on.');
INSERT INTO "lifecycle_stages" VALUES('apple','mosaic_virus',10,'The virus lives in the tree''s sap.');
INSERT INTO "lifecycle_stages" VALUES('apple','mosaic_virus',20,'It passes to new trees through grafted buds and rootstocks.');
INSERT INTO "lifecycle_stages" VALUES('apple','mosaic_virus',30,'Spring leaves show cream spots and vein bands.');
INSERT INTO "lifecycle_stages" VALUES('apple','mosaic_virus',40,'Every tree grafted from it is infected too.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','anthracnose',10,'Spores overwinter on twigs and buds.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','anthracnose',20,'Rain splashes them onto green berries.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','anthracnose',30,'Infection stays hidden until the fruit ripens.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','anthracnose',40,'Ripe berries soften and ooze orange spores.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','botrytis_blight',10,'The fungus lives on dead plant matter.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','botrytis_blight',20,'Spores land on blossoms in cool, wet weather.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','botrytis_blight',30,'Flowers brown and grow grey fuzz.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','botrytis_blight',40,'Mould spreads to fruit and shoots.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','mummy_berry',10,'Mummies on the ground grow cup fungi in spring.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','mummy_berry',20,'Their spores blight young shoots.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','mummy_berry',30,'Spores from the shoots infect the flowers.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','mummy_berry',40,'Berries become mummies and drop.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','rust',10,'Spores blow from hemlocks or infected bushes.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','rust',20,'They infect leaves in warm, humid weather.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','rust',30,'Yellow spots form, with orange pustules underneath.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','rust',40,'New spores spread from bush to bush.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','scorch',10,'Aphids feed on an infected bush.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','scorch',20,'They carry the virus to healthy bushes.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','scorch',30,'At bloom, flowers and young leaves die back.');
INSERT INTO "lifecycle_stages" VALUES('blueberry','scorch',40,'Leaf edges scorch; the bush declines.');
INSERT INTO "lifecycle_stages" VALUES('cherry','powdery_mildew',10,'The fungus overwinters on the tree and in leaf litter.');
INSERT INTO "lifecycle_stages" VALUES('cherry','powdery_mildew',20,'Spores infect young leaves in warm, humid weather.');
INSERT INTO "lifecycle_stages" VALUES('cherry','powdery_mildew',30,'White powdery patches spread and leaves curl.');
INSERT INTO "lifecycle_stages" VALUES('cherry','powdery_mildew',40,'New spores spread through the canopy.');
INSERT INTO "lifecycle_stages" VALUES('cherry','leaf_spot',10,'The fungus overwinters in fallen leaves.');
INSERT INTO "lifecycle_stages" VALUES('cherry','leaf_spot',20,'Spring rain splashes spores onto young leaves.');
INSERT INTO "lifecycle_stages" VALUES('cherry','leaf_spot',30,'Purple spots appear; spores form underneath.');
INSERT INTO "lifecycle_stages" VALUES('cherry','leaf_spot',40,'Leaves yellow and drop, and new spores spread.');
INSERT INTO "lifecycle_stages" VALUES('corn','gray_leaf_spot',10,'The fungus survives on maize residue on the surface.');
INSERT INTO "lifecycle_stages" VALUES('corn','gray_leaf_spot',20,'Spores splash and blow onto lower leaves in humid weather.');
INSERT INTO "lifecycle_stages" VALUES('corn','gray_leaf_spot',30,'Narrow rectangular grey lesions form between the veins.');
INSERT INTO "lifecycle_stages" VALUES('corn','gray_leaf_spot',40,'Lesions join and the infection climbs the plant.');
INSERT INTO "lifecycle_stages" VALUES('corn','common_rust',10,'Spores blow in on the wind each year.');
INSERT INTO "lifecycle_stages" VALUES('corn','common_rust',20,'They infect leaves wet from dew.');
INSERT INTO "lifecycle_stages" VALUES('corn','common_rust',30,'Cinnamon-brown pustules break through both leaf surfaces.');
INSERT INTO "lifecycle_stages" VALUES('corn','common_rust',40,'Pustules release new spores that spread up the plant.');
INSERT INTO "lifecycle_stages" VALUES('corn','northern_leaf_blight',10,'The fungus survives on maize residue.');
INSERT INTO "lifecycle_stages" VALUES('corn','northern_leaf_blight',20,'Spores reach the lower leaves in wet, mild weather.');
INSERT INTO "lifecycle_stages" VALUES('corn','northern_leaf_blight',30,'Long grey-green lesions form and turn tan.');
INSERT INTO "lifecycle_stages" VALUES('corn','northern_leaf_blight',40,'Spores from the lesions spread to upper leaves.');
INSERT INTO "lifecycle_stages" VALUES('corn','smut',10,'Spores survive in the soil and on debris.');
INSERT INTO "lifecycle_stages" VALUES('corn','smut',20,'They blow or splash onto young ears, tassels and stalks.');
INSERT INTO "lifecycle_stages" VALUES('corn','smut',30,'Infected tissue swells into silvery galls.');
INSERT INTO "lifecycle_stages" VALUES('corn','smut',40,'Galls burst and release black spores.');
INSERT INTO "lifecycle_stages" VALUES('grape','black_rot',10,'The fungus overwinters in mummified berries and old canes.');
INSERT INTO "lifecycle_stages" VALUES('grape','black_rot',20,'Spring rain releases spores onto young leaves and shoots.');
INSERT INTO "lifecycle_stages" VALUES('grape','black_rot',30,'Tan spots with dark borders and black dots appear.');
INSERT INTO "lifecycle_stages" VALUES('grape','black_rot',40,'Berries rot and become mummies for next year.');
INSERT INTO "lifecycle_stages" VALUES('grape','esca',10,'Fungal spores enter through pruning wounds.');
INSERT INTO "lifecycle_stages" VALUES('grape','esca',20,'The fungi grow in the wood for years, unseen.');
INSERT INTO "lifecycle_stages" VALUES('grape','esca',30,'In summer, leaves show tiger stripes and berries get dark spots.');
INSERT INTO "lifecycle_stages" VALUES('grape','esca',40,'The vine declines or suddenly collapses.');
INSERT INTO "lifecycle_stages" VALUES('grape','leaf_blight',10,'The fungus survives on fallen leaves.');
INSERT INTO "lifecycle_stages" VALUES('grape','leaf_blight',20,'Spores infect leaves in warm, humid weather.');
INSERT INTO "lifecycle_stages" VALUES('grape','leaf_blight',30,'Irregular dark spots appear and dry out.');
INSERT INTO "lifecycle_stages" VALUES('grape','leaf_blight',40,'Older leaves yellow and drop.');
INSERT INTO "lifecycle_stages" VALUES('grape','downy_mildew',10,'Spores survive in leaf litter and soil.');
INSERT INTO "lifecycle_stages" VALUES('grape','downy_mildew',20,'Rain splashes them onto wet leaves.');
INSERT INTO "lifecycle_stages" VALUES('grape','downy_mildew',30,'Oily yellow spots appear, white down forms underneath.');
INSERT INTO "lifecycle_stages" VALUES('grape','downy_mildew',40,'New spores spread on wind and rain to leaves and berries.');
INSERT INTO "lifecycle_stages" VALUES('grape','leafroll',10,'The virus is in the vine''s sap.');
INSERT INTO "lifecycle_stages" VALUES('grape','leafroll',20,'Mealybugs feeding on it pick it up.');
INSERT INTO "lifecycle_stages" VALUES('grape','leafroll',30,'They carry it to nearby vines; cuttings carry it farther.');
INSERT INTO "lifecycle_stages" VALUES('grape','leafroll',40,'Leaves redden and roll from late summer.');
INSERT INTO "lifecycle_stages" VALUES('orange','citrus_greening',10,'Psyllids pick up the bacteria feeding on infected trees.');
INSERT INTO "lifecycle_stages" VALUES('orange','citrus_greening',20,'They carry them to new shoots of healthy trees.');
INSERT INTO "lifecycle_stages" VALUES('orange','citrus_greening',30,'The bacteria spread through the tree''s food-conducting tissue.');
INSERT INTO "lifecycle_stages" VALUES('orange','citrus_greening',40,'Leaves mottle, fruit is poor and the tree declines.');
INSERT INTO "lifecycle_stages" VALUES('orange','citrus_canker',10,'Bacteria survive in spots on leaves, twigs and fruit.');
INSERT INTO "lifecycle_stages" VALUES('orange','citrus_canker',20,'Wind-driven rain splashes them onto new growth.');
INSERT INTO "lifecycle_stages" VALUES('orange','citrus_canker',30,'They enter through pores and wounds.');
INSERT INTO "lifecycle_stages" VALUES('orange','citrus_canker',40,'Raised corky spots with yellow halos form.');
INSERT INTO "lifecycle_stages" VALUES('peach','bacterial_spot',10,'The bacteria overwinter in twig cankers.');
INSERT INTO "lifecycle_stages" VALUES('peach','bacterial_spot',20,'Spring rain splashes them onto young leaves.');
INSERT INTO "lifecycle_stages" VALUES('peach','bacterial_spot',30,'Small purple-brown spots form, then drop out as shot holes.');
INSERT INTO "lifecycle_stages" VALUES('peach','bacterial_spot',40,'Leaves yellow and drop; fruit is pitted.');
INSERT INTO "lifecycle_stages" VALUES('peach','anthracnose',10,'The fungus survives on mummies and twigs.');
INSERT INTO "lifecycle_stages" VALUES('peach','anthracnose',20,'Rain splashes spores onto the fruit.');
INSERT INTO "lifecycle_stages" VALUES('peach','anthracnose',30,'Sunken spots with spore rings form as fruit ripens.');
INSERT INTO "lifecycle_stages" VALUES('peach','anthracnose',40,'Rotting fruit spreads it to its neighbours.');
INSERT INTO "lifecycle_stages" VALUES('peach','brown_rot',10,'The fungus overwinters in mummies and cankers.');
INSERT INTO "lifecycle_stages" VALUES('peach','brown_rot',20,'Spring spores blight the blossoms.');
INSERT INTO "lifecycle_stages" VALUES('peach','brown_rot',30,'Near harvest, spores infect ripening fruit.');
INSERT INTO "lifecycle_stages" VALUES('peach','brown_rot',40,'Rotting fruit shrivels into new mummies.');
INSERT INTO "lifecycle_stages" VALUES('peach','leaf_curl',10,'Spores overwinter on bark and bud scales.');
INSERT INTO "lifecycle_stages" VALUES('peach','leaf_curl',20,'Cool, wet weather at bud break lets them infect.');
INSERT INTO "lifecycle_stages" VALUES('peach','leaf_curl',30,'Leaves thicken, pucker and turn red.');
INSERT INTO "lifecycle_stages" VALUES('peach','leaf_curl',40,'A grey bloom of new spores forms before the leaves drop.');
INSERT INTO "lifecycle_stages" VALUES('peach','rust',10,'Spores survive in twig cankers or blow in.');
INSERT INTO "lifecycle_stages" VALUES('peach','rust',20,'Wet, warm weather lets them infect leaves.');
INSERT INTO "lifecycle_stages" VALUES('peach','rust',30,'Yellow spots form, with rust pustules beneath.');
INSERT INTO "lifecycle_stages" VALUES('peach','rust',40,'New spores spread through the tree.');
INSERT INTO "lifecycle_stages" VALUES('peach','scab',10,'The fungus overwinters in twig lesions.');
INSERT INTO "lifecycle_stages" VALUES('peach','scab',20,'Spring rain spreads spores to young fruit.');
INSERT INTO "lifecycle_stages" VALUES('peach','scab',30,'Spots appear about 6 weeks later.');
INSERT INTO "lifecycle_stages" VALUES('peach','scab',40,'Spots join and the skin cracks.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','fire_blight',10,'Bacteria survive in cankers on host plants.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','fire_blight',20,'Rain and insects carry them to flowers and shoots.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','fire_blight',30,'Shoot tips blacken and bend over.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','fire_blight',40,'Ooze from the shoots spreads them further.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','gray_mold',10,'The fungus lives on dead plant material.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','gray_mold',20,'Spores infect the flowers in wet weather.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','gray_mold',30,'The berries rot as they ripen.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','gray_mold',40,'Grey spores spread to neighbouring fruit.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','leaf_spot',10,'The fungus overwinters on leaves and canes.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','leaf_spot',20,'Rain splashes spores onto new leaves.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','leaf_spot',30,'Purple spots with pale centres form.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','leaf_spot',40,'Leaves drop early.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','yellow_rust',10,'Spores overwinter on leaves and canes.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','yellow_rust',20,'In spring they infect new leaves.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','yellow_rust',30,'Orange pustules form underneath.');
INSERT INTO "lifecycle_stages" VALUES('raspberry','yellow_rust',40,'Black winter spores form in autumn.');
INSERT INTO "lifecycle_stages" VALUES('soybean','rust',10,'Spores blow in from warmer regions.');
INSERT INTO "lifecycle_stages" VALUES('soybean','rust',20,'They infect leaves wet for several hours.');
INSERT INTO "lifecycle_stages" VALUES('soybean','rust',30,'Tan lesions with pustules form underneath.');
INSERT INTO "lifecycle_stages" VALUES('soybean','rust',40,'Millions of new spores spread up the field.');
INSERT INTO "lifecycle_stages" VALUES('soybean','bacterial_blight',10,'Bacteria survive in residue and seed.');
INSERT INTO "lifecycle_stages" VALUES('soybean','bacterial_blight',20,'Wind-driven rain splashes them onto leaves.');
INSERT INTO "lifecycle_stages" VALUES('soybean','bacterial_blight',30,'Water-soaked spots turn brown with halos.');
INSERT INTO "lifecycle_stages" VALUES('soybean','bacterial_blight',40,'Dead tissue falls out.');
INSERT INTO "lifecycle_stages" VALUES('soybean','brown_spot',10,'The fungus overwinters on residue.');
INSERT INTO "lifecycle_stages" VALUES('soybean','brown_spot',20,'Rain splashes spores to the lowest leaves.');
INSERT INTO "lifecycle_stages" VALUES('soybean','brown_spot',30,'Brown spots with yellow surrounds form.');
INSERT INTO "lifecycle_stages" VALUES('soybean','brown_spot',40,'It climbs the plant in wet weather.');
INSERT INTO "lifecycle_stages" VALUES('soybean','downy_mildew',10,'Spores survive in residue and seed.');
INSERT INTO "lifecycle_stages" VALUES('soybean','downy_mildew',20,'Cool, humid weather lets them infect.');
INSERT INTO "lifecycle_stages" VALUES('soybean','downy_mildew',30,'Pale spots form with grey tufts underneath.');
INSERT INTO "lifecycle_stages" VALUES('soybean','downy_mildew',40,'Pods and seed can be infected.');
INSERT INTO "lifecycle_stages" VALUES('soybean','frogeye_leaf_spot',10,'The fungus survives on residue and seed.');
INSERT INTO "lifecycle_stages" VALUES('soybean','frogeye_leaf_spot',20,'Warm, humid weather spreads spores.');
INSERT INTO "lifecycle_stages" VALUES('soybean','frogeye_leaf_spot',30,'Grey spots with purple rings form.');
INSERT INTO "lifecycle_stages" VALUES('soybean','frogeye_leaf_spot',40,'Spots join and leaves drop.');
INSERT INTO "lifecycle_stages" VALUES('soybean','mosaic',10,'Infected seed gives infected seedlings.');
INSERT INTO "lifecycle_stages" VALUES('soybean','mosaic',20,'Aphids carry the virus to nearby plants.');
INSERT INTO "lifecycle_stages" VALUES('soybean','mosaic',30,'Young leaves mottle and pucker.');
INSERT INTO "lifecycle_stages" VALUES('soybean','mosaic',40,'Seed from infected plants is mottled.');
INSERT INTO "lifecycle_stages" VALUES('squash','powdery_mildew',10,'Spores arrive on the wind from other cucurbits.');
INSERT INTO "lifecycle_stages" VALUES('squash','powdery_mildew',20,'They infect leaves without needing them to be wet.');
INSERT INTO "lifecycle_stages" VALUES('squash','powdery_mildew',30,'White powdery spots spread over the leaf.');
INSERT INTO "lifecycle_stages" VALUES('squash','powdery_mildew',40,'Leaves yellow and die, and spores spread on.');
INSERT INTO "lifecycle_stages" VALUES('squash','bacterial_wilt',10,'The bacteria overwinter inside cucumber beetles.');
INSERT INTO "lifecycle_stages" VALUES('squash','bacterial_wilt',20,'Feeding beetles infect the leaves.');
INSERT INTO "lifecycle_stages" VALUES('squash','bacterial_wilt',30,'Bacteria fill the water vessels.');
