INSERT INTO "methods" VALUES('tomato','early_blight','sanitation','Remove affected tissue and dispose of it','Reduces the spore source','Existing lesions on retained tissue stay.','treatment_content');
INSERT INTO "methods" VALUES('tomato','early_blight','cultural','Water at the base, keep foliage dry','Reduces splash and leaf wetness','Does not remove existing infection.','treatment_content');
INSERT INTO "methods" VALUES('tomato','early_blight','protect','Protective fungicide where justified','Protects healthy tissue during high-risk weather','Does not cure lesions; product and dose follow the local label.','treatment_content');
INSERT INTO "methods" VALUES('tomato','early_blight','future','Rotation and resistant or tolerant varieties','Lowers risk in later crops','Not an immediate treatment.','treatment_content');
INSERT INTO "methods" VALUES('tomato','bacterial_spot','hygiene','Dry handling, tool and hand sanitation, selective removal','Limits spread','Established infection is managed, not cured.','treatment_content');
INSERT INTO "methods" VALUES('tomato','bacterial_spot','irrigation','Drip instead of overhead irrigation','Stops splash dispersal','Does not remove existing infection.','treatment_content');
INSERT INTO "methods" VALUES('tomato','bacterial_spot','copper','Copper-based protection where justified','May slow spread on new tissue','Limited efficacy; copper resistance is documented.','treatment_content');
INSERT INTO "methods" VALUES('tomato','late_blight','contain','Bag and remove infected material','Removes the spore source','Infected material cannot be saved.','treatment_content');
INSERT INTO "methods" VALUES('tomato','late_blight','protect','Late-blight-active protection for healthy hosts','Protects neighbours','Ordinary fungicides cannot be assumed effective against a water mould.','treatment_content');
INSERT INTO "methods" VALUES('tomato','late_blight','clean_stock','Clean transplants','Restarts with healthy plants','Windborne spores can still arrive.','treatment_content');
INSERT INTO "methods" VALUES('tomato','leaf_mold','environment','Ventilation, spacing and dry foliage','Reduces prolonged humidity','Must be maintained.','treatment_content');
INSERT INTO "methods" VALUES('tomato','leaf_mold','sanitation','Remove affected tissue','Removes spore sources','Old patches remain.','treatment_content');
INSERT INTO "methods" VALUES('tomato','leaf_mold','protect','Protective fungicide as a supplement','Protects healthy tissue','Supplements, not replaces, environmental control.','treatment_content');
INSERT INTO "methods" VALUES('tomato','septoria_leaf_spot','sanitation','Remove affected tissue; manage residue','Removes spore sources','Retained tissue keeps its spots.','treatment_content');
INSERT INTO "methods" VALUES('tomato','septoria_leaf_spot','cultural','Dry foliage, drip irrigation, rotation','Reduces splash and leaf wetness','Prevention, not cure.','treatment_content');
INSERT INTO "methods" VALUES('tomato','septoria_leaf_spot','protect','Protective fungicide as a supplement','Protects healthy tissue','Does not remove existing spots.','treatment_content');
INSERT INTO "methods" VALUES('tomato','spider_mites','conditions','Correct water stress and dust','Less favourable for mites','Does not remove a colony alone.','treatment_content');
INSERT INTO "methods" VALUES('tomato','spider_mites','biological','Conserve or release predatory mites','Suppresses mites without harming natural enemies','Needs time and compatible treatments.','treatment_content');
INSERT INTO "methods" VALUES('tomato','spider_mites','contact','Directed water wash, then labelled insecticidal soap or oil','Knocks back the colony','Contact only; repeat checks needed.','treatment_content');
INSERT INTO "methods" VALUES('tomato','target_spot','sanitation','Remove infected material; manage residue','Reduces inoculum','Advanced damage remains.','treatment_content');
INSERT INTO "methods" VALUES('tomato','target_spot','drying','Shorten leaf wetness','Less infection','Must be maintained.','treatment_content');
INSERT INTO "methods" VALUES('tomato','target_spot','programme','Effective fungicide programme with resistance management','Important under high pressure','Do not assume an early-blight claim applies.','treatment_content');
INSERT INTO "methods" VALUES('tomato','yellow_leaf_curl_virus','contain','Contain vectors, then remove infected material','Stops it acting as a virus source','Infected tissue is not cured.','treatment_content');
INSERT INTO "methods" VALUES('tomato','yellow_leaf_curl_virus','vectors','Whitefly management and exclusion mesh','Prevents reinfection','Requires continued monitoring.','treatment_content');
INSERT INTO "methods" VALUES('tomato','yellow_leaf_curl_virus','clean_stock','Clean, resistant transplants','Healthy replacement','Resistance may not eliminate symptoms.','treatment_content');
INSERT INTO "methods" VALUES('tomato','mosaic_virus','remove','Remove infected material','Removes the virus source','Cannot be cured.','treatment_content');
INSERT INTO "methods" VALUES('tomato','mosaic_virus','sanitation','Validated cleaning of hands, tools, supports and surfaces','Stops mechanical spread','Must follow validated procedures.','treatment_content');
INSERT INTO "methods" VALUES('tomato','mosaic_virus','clean_stock','Clean planting material and resistance','Healthy replacement','Resistance varies by strain.','treatment_content');
INSERT INTO "methods" VALUES('apple','apple_scab','sanitation','Destroy fallen and affected leaves','Removes the overwintering spore source','Reduces, does not eliminate, spring spores.','treatment_content');
INSERT INTO "methods" VALUES('apple','apple_scab','drying','Faster drying of foliage','Shorter infection periods','Does not remove existing scabs.','treatment_content');
INSERT INTO "methods" VALUES('apple','apple_scab','protect','Locally approved scab fungicide timed to infection risk','Protects susceptible growth','Existing scabs remain.','treatment_content');
INSERT INTO "methods" VALUES('apple','apple_scab','resistance','Scab-resistant varieties','Long-term prevention','For future planting.','treatment_content');
INSERT INTO "methods" VALUES('apple','black_rot','sanitation','Remove mummies, dead wood and cankers','Removes the main inoculum','Central to control.','treatment_content');
INSERT INTO "methods" VALUES('apple','black_rot','protect','Protection with an appropriate fungicide','Protects healthy tissue','Rotten fruit is not repaired.','treatment_content');
INSERT INTO "methods" VALUES('apple','cedar_apple_rust','resistance','Resistant apple varieties','Main defence','For future planting.','treatment_content');
INSERT INTO "methods" VALUES('apple','cedar_apple_rust','galls','Remove accessible juniper galls before spore release','Reduces local spores','Cannot exclude windborne spores.','treatment_content');
INSERT INTO "methods" VALUES('apple','cedar_apple_rust','protect','Timely spring protection','Protects new leaves','Does not repair existing spots.','treatment_content');
INSERT INTO "methods" VALUES('cherry','powdery_mildew','canopy','Better light and airflow','Less favourable conditions','Does not remove mildew alone.','treatment_content');
INSERT INTO "methods" VALUES('cherry','powdery_mildew','protect','Cherry-labelled mildew treatment','Suppresses mildew','Depends on growth stage, temperature and compatibility.','treatment_content');
INSERT INTO "methods" VALUES('peach','bacterial_spot','cultural','Water, nutrition, reduced stress','Healthier trees','Gradual.','treatment_content');
INSERT INTO "methods" VALUES('peach','bacterial_spot','resistance','Resistant varieties','Main long-term measure','For future planting.','treatment_content');
INSERT INTO "methods" VALUES('peach','bacterial_spot','copper','Copper only in label-permitted stages','Limited protection','Leaf injury and label limits apply.','treatment_content');
INSERT INTO "methods" VALUES('pepper','bacterial_spot','clean_stock','Clean seed and transplants','Prevents introduction','Does not cure infected plants.','treatment_content');
INSERT INTO "methods" VALUES('pepper','bacterial_spot','hygiene','Dry handling, sanitation, selective removal','Limits spread','Managed, not cured.','treatment_content');
INSERT INTO "methods" VALUES('pepper','bacterial_spot','copper','Copper where justified','May slow spread','Resistance documented.','treatment_content');
INSERT INTO "methods" VALUES('strawberry','leaf_scorch','water','Drip irrigation and weed control','Drier canopy','Ongoing.','treatment_content');
