INSERT INTO "methods" VALUES('strawberry','leaf_scorch','fungicide','Fungicide depending on pressure','For heavy pressure','Mild cases may need none.','treatment_content');
INSERT INTO "methods" VALUES('corn','gray_leaf_spot','resistance','Resistant hybrids','Main defence','For the next crop.','treatment_content');
INSERT INTO "methods" VALUES('corn','gray_leaf_spot','rotation','Rotation and residue management','Reduces inoculum','Not an in-season fix.','treatment_content');
INSERT INTO "methods" VALUES('corn','gray_leaf_spot','fungicide','Foliar fungicide only when justified','Protects functional leaves','Only when stage, susceptibility and weather justify it.','treatment_content');
INSERT INTO "methods" VALUES('corn','common_rust','resistance','Resistant hybrids','Main defence','For future crops.','treatment_content');
INSERT INTO "methods" VALUES('corn','common_rust','monitor','Monitoring for mild disease','Avoids unnecessary spraying','Requires follow-up.','treatment_content');
INSERT INTO "methods" VALUES('corn','common_rust','fungicide','Early justified fungicide on susceptible crops','For susceptible crops','Not needed in mild cases.','treatment_content');
INSERT INTO "methods" VALUES('corn','northern_leaf_blight','resistance','Resistant hybrids','Main defence','For the next crop.','treatment_content');
INSERT INTO "methods" VALUES('corn','northern_leaf_blight','rotation','Rotation and residue','Reduce inoculum','Not an in-season fix.','treatment_content');
INSERT INTO "methods" VALUES('corn','northern_leaf_blight','fungicide','Fungicide for early disease on susceptible crops','Protects healthy tissue','Existing lesions remain.','treatment_content');
INSERT INTO "methods" VALUES('potato','early_blight','care','Appropriate irrigation and nutrition','Less stress','Gradual.','treatment_content');
INSERT INTO "methods" VALUES('potato','early_blight','clean','Clean seed, rotation, volunteer control','Fewer sources','Long-term.','treatment_content');
INSERT INTO "methods" VALUES('potato','early_blight','protect','Protection where pressure warrants','Protects tissue','Old lesions remain.','treatment_content');
INSERT INTO "methods" VALUES('potato','late_blight','contain','Contain infected foliage and tubers','Removes spore sources','Infected material is not saved.','treatment_content');
INSERT INTO "methods" VALUES('potato','late_blight','protect','Late-blight-active protection for healthy hosts','Protects neighbours','Ordinary fungicides cannot be assumed effective.','treatment_content');
INSERT INTO "methods" VALUES('potato','late_blight','clean_seed','Certified seed potatoes','Healthy later crop','Windborne spores can still arrive.','treatment_content');
INSERT INTO "methods" VALUES('grape','black_rot','sanitation','Remove mummies and infected material','Removes inoculum','Must include ground mummies.','treatment_content');
INSERT INTO "methods" VALUES('grape','black_rot','drying','Canopy drying','Shorter wetness','Ongoing.','treatment_content');
INSERT INTO "methods" VALUES('grape','black_rot','protect','Protection during susceptible stages','Protects new tissue','Infected berries are not saved.','treatment_content');
INSERT INTO "methods" VALUES('grape','esca','prevention','Pruning-wound prevention','Prevents new infections','Future practice.','treatment_content');
INSERT INTO "methods" VALUES('grape','esca','replace','Replace severely affected vines','Restores production','The original vine is not cured.','treatment_content');
INSERT INTO "methods" VALUES('grape','leaf_blight','protect','Disease-specific protection for susceptible cultivars','Keeps foliage functional','Generic copper/Bordeaux cannot be assumed effective.','treatment_content');
INSERT INTO "methods" VALUES('grape','leaf_blight','cultivar','Cultivar-appropriate management','Matches susceptibility','Varies by cultivar.','treatment_content');
