INSERT INTO "prevention_measures" VALUES('tomato','early_blight',10,'CropHygiene','Remove and destroy infected debris','Early blight overwinters on crop residue and volunteer plants. Clear fallen leaves and end-of-season debris rather than leaving them in the bed.');
