INSERT INTO "treatment_steps" VALUES('mango','powdery_mildew','mango_powdery_mildew_1',20,'Open the canopy','Prune for airflow and light.','Shade and still air favour mildew.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
