INSERT INTO "treatment_steps" VALUES('mango','sooty_mould','mango_sooty_mould_0',10,'Control the sap-sucking insects','Deal with hoppers, scales or mealybugs as advised locally.','No honeydew, no sooty mould.','AdjustSetting',3,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('mango','sooty_mould','mango_sooty_mould_1',20,'Wash the coating off','Spray water (with a mild soap where advised) on badly coated leaves.','Restores light to the leaves.','SprayApply',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('mango','sooty_mould','mango_sooty_mould_2',30,'Control ants','Keep ants off the tree.','Ants protect the insects that make honeydew.','Informational',2,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('maple','tar_spot','maple_tar_spot_0',10,'Rake up fallen leaves','Collect and compost or remove leaves in autumn.','The fungus overwinters in them.','GrabAndRemove',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('maple','tar_spot','maple_tar_spot_1',20,'Keep the tree vigorous','Water in drought and mulch the root area.','Healthy trees are not harmed.','AdjustSetting',3,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('maple','tar_spot','maple_tar_spot_2',30,'No spraying needed','Fungicides are not normally needed for tar spot.','The disease does not threaten the tree.','Informational',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('plum','bacterial_spot','plum_bacterial_spot_0',10,'Prune out cankered twigs','Cut out twigs with dark cankers in dry weather.','Cankers carry the bacteria.','TapRegion',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('plum','bacterial_spot','plum_bacterial_spot_1',20,'Keep trees vigorous','Feed and water moderately.','Stressed trees suffer more.','AdjustSetting',3,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('plum','bacterial_spot','plum_bacterial_spot_2',30,'Copper spray where advised','Spray a registered copper product following the label.','Protects leaves and fruit.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('plum','brown_rot','plum_brown_rot_0',10,'Remove rotting fruit and mummies','Pick off rotting fruit and all mummies, also from the ground.','They are the main spore source.','GrabAndRemove',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('plum','brown_rot','plum_brown_rot_1',20,'Prune out blighted twigs','Cut out twigs with cankers well below the damage.','Cankers release spores for years.','TapRegion',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('plum','brown_rot','plum_brown_rot_2',30,'Fungicide at bloom and before harvest','Spray a registered product at the label''s timings.','Blossoms and ripening fruit are the vulnerable stages.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('plum','pocket_disease','plum_pocket_disease_0',10,'Remove pocketed fruit','Pick off pocketed fruit when the plants are dry and take them away.','Fewer spores are left to spread.','GrabAndRemove',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('plum','pocket_disease','plum_pocket_disease_1',20,'Prune out affected shoots','Remove twigs with pockets.','Reduces spores on the tree.','TapRegion',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('plum','pocket_disease','plum_pocket_disease_2',30,'Dormant spray next winter','Apply a registered fungicide before bud swell.','Only a dormant spray prevents it.','SprayApply',4,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('plum','plum_pox_virus','plum_plum_pox_virus_0',10,'Report suspected cases','Plum pox is notifiable in many countries.','Official control stops its spread.','Informational',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('plum','plum_pox_virus','plum_plum_pox_virus_1',20,'Remove infected trees','Remove confirmed trees with their roots.','There is no cure.','GrabAndRemove',3,0,-2.000000029802322388e-01,-1.0000000149011611938e-01,0.0,-1.0000000149011611938e-01,0.0,0.0);
INSERT INTO "treatment_steps" VALUES('plum','plum_pox_virus','plum_plum_pox_virus_2',30,'Control aphids','Follow local advice on aphid control.','Aphids spread it between trees.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('plum','rust','plum_rust_0',10,'Clear fallen leaves','Rake and remove leaves in autumn.','Reduces spores near the tree.','GrabAndRemove',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('plum','rust','plum_rust_1',20,'Prune out cankered twigs','Remove twigs with rust cankers in spring.','Cankers start early infections.','TapRegion',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('plum','rust','plum_rust_2',30,'Fungicide when rust appears early','Spray a registered product following the label.','Protects leaves until harvest.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','blast','rice_blast_0',10,'Scout leaves and necks','Check for diamond lesions and blackened necks.','Early detection allows control.','TapRegion',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('rice','blast','rice_blast_1',20,'Protective spray','Spray a registered fungicide at the advised growth stages on the label''s schedule.','Protects healthy growth; it cannot cure what is already infected.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','blast','rice_blast_2',30,'Cut back nitrogen','Split the nitrogen and avoid heavy doses.','Lush rice is more susceptible.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','sheath_blight','rice_sheath_blight_0',10,'Scout the water line','Check the lower sheaths in dense patches.','It starts low.','TapRegion',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('rice','sheath_blight','rice_sheath_blight_1',20,'Protective spray','Spray a registered fungicide if it climbs on the label''s schedule.','Protects healthy growth; it cannot cure what is already infected.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','sheath_blight','rice_sheath_blight_2',30,'Use moderate seeding and nitrogen','Plan wider spacing next crop.','Dense canopies favour it.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','bacterial_leaf_blight','rice_bacterial_leaf_blight_0',10,'Drain the field briefly','Drain and let the field dry for a few days if advised.','Flood water spreads the bacteria.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','bacterial_leaf_blight','rice_bacterial_leaf_blight_1',20,'Hold back nitrogen','Skip or split the next nitrogen dose.','Lush rice is more susceptible.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','bacterial_leaf_blight','rice_bacterial_leaf_blight_2',30,'Clean up stubble and weeds','Remove infected stubble, straw and grass weeds after harvest.','They carry the bacteria to the next crop.','Informational',2,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('rice','brown_spot','rice_brown_spot_0',10,'Feed the soil','Correct potassium, silicon and nitrogen shortages as advised.','Well-fed rice resists brown spot.','AdjustSetting',3,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','brown_spot','rice_brown_spot_1',20,'Protective spray','Spray a registered fungicide where advised on the label''s schedule.','Protects healthy growth; it cannot cure what is already infected.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','brown_spot','rice_brown_spot_2',30,'Use clean seed next season','Sow certified or treated seed.','Seed carries the fungus.','Informational',2,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('rice','tungro','rice_tungro_0',10,'Remove infected plants','Pull out yellowed, stunted plants and bury them.','They are the virus source for leafhoppers.','GrabAndRemove',1,0,-2.000000029802322388e-01,-1.0000000149011611938e-01,0.0,-1.0000000149011611938e-01,0.0,0.0);
INSERT INTO "treatment_steps" VALUES('rice','tungro','rice_tungro_1',20,'Watch the leafhoppers','Check leafhopper numbers and act as advised locally.','Leafhoppers spread the virus.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('rice','tungro','rice_tungro_2',30,'Plough in stubble after harvest','Destroy stubble and ratoons.','Regrowth keeps the virus going between crops.','Informational',2,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','mosaic','sugarcane_mosaic_0',10,'Remove infected stools early','Dig out mottled plants in young crops.','Fewer sources for aphids.','GrabAndRemove',2,0,-2.000000029802322388e-01,-1.0000000149011611938e-01,0.0,-1.0000000149011611938e-01,0.0,0.0);
INSERT INTO "treatment_steps" VALUES('sugarcane','mosaic','sugarcane_mosaic_1',20,'Use healthy seed cane','Plant setts from disease-free nurseries.','The main source of the virus.','Informational',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','mosaic','sugarcane_mosaic_2',30,'Control grass weeds','Remove grass weeds round the field.','They host the virus and aphids.','AdjustSetting',2,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','red_rot','sugarcane_red_rot_0',10,'Remove and destroy affected clumps','Dig out infected clumps with their roots and burn or bury them.','They release masses of spores.','GrabAndRemove',2,0,-2.000000029802322388e-01,-1.0000000149011611938e-01,0.0,-1.0000000149011611938e-01,0.0,0.0);
INSERT INTO "treatment_steps" VALUES('sugarcane','red_rot','sugarcane_red_rot_1',20,'Improve drainage','Avoid waterlogging and don''t let water run from infected plots.','Water spreads the spores.','AdjustSetting',3,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','red_rot','sugarcane_red_rot_2',30,'Plant treated, healthy setts of a resistant variety','Use resistant varieties and treated seed cane next time.','The main controls.','Informational',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','rust','sugarcane_rust_0',10,'Scout the leaves','Check how many leaves carry pustules.','Most varieties tolerate light rust.','TapRegion',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','rust','sugarcane_rust_1',20,'Protective spray','Spray a registered fungicide on susceptible varieties on the label''s schedule.','Protects healthy growth; it cannot cure what is already infected.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','rust','sugarcane_rust_2',30,'Plan resistant varieties','Choose rust-resistant varieties next planting.','The main control.','Informational',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','yellow_leaf','sugarcane_yellow_leaf_0',10,'Mark yellowed stools','Note where plants with yellow midribs are.','Shows how widespread it is.','TapRegion',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','yellow_leaf','sugarcane_yellow_leaf_1',20,'Use virus-free seed cane','Plant tissue-culture or certified setts next time.','Breaks the chain of infected seed.','Informational',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('sugarcane','yellow_leaf','sugarcane_yellow_leaf_2',30,'Control aphids where advised','Follow local advice on aphid control.','Aphids spread the virus.','AdjustSetting',2,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('tobacco','blue_mold','tobacco_blue_mold_0',10,'Remove infected plants in seedbeds','Pick off infected plants in seedbeds when the plants are dry and take them away.','Stops spores spreading.','GrabAndRemove',1,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('tobacco','blue_mold','tobacco_blue_mold_1',20,'Ventilate seedbeds and space plants','Reduce humidity.','Spores need wet leaves.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('tobacco','blue_mold','tobacco_blue_mold_2',30,'Protective spray','Spray a registered product for blue mold on the label''s schedule.','Protects healthy growth; it cannot cure what is already infected.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('tobacco','brown_spot','tobacco_brown_spot_0',10,'Remove lower spotted leaves','Pick off lower spotted leaves when the plants are dry and take them away.','Fewer spores are left to spread.','TapRegion',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('tobacco','brown_spot','tobacco_brown_spot_1',20,'Harvest leaves on time','Do not leave mature leaves on the plant too long.','Mature leaves are most susceptible.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('tobacco','brown_spot','tobacco_brown_spot_2',30,'Protective spray','Spray a registered fungicide on the label''s schedule.','Protects healthy growth; it cannot cure what is already infected.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('tobacco','frogeye_leaf_spot','tobacco_frogeye_leaf_spot_0',10,'Remove spotted lower leaves','Pick off spotted lower leaves when the plants are dry and take them away.','Fewer spores are left to spread.','TapRegion',2,0,-1.0000000149011611938e-01,-2.199999988079071044e-01,-7.999999821186065673e-02,0.0,3.999999910593032836e-02,0.0);
INSERT INTO "treatment_steps" VALUES('tobacco','frogeye_leaf_spot','tobacco_frogeye_leaf_spot_1',20,'Harvest on time','Do not leave ripe leaves in the field.','Ripe leaves are most susceptible.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('tobacco','frogeye_leaf_spot','tobacco_frogeye_leaf_spot_2',30,'Protective spray','Spray a registered fungicide on the label''s schedule.','Protects healthy growth; it cannot cure what is already infected.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('tobacco','mosaic_virus','tobacco_mosaic_virus_0',10,'Remove infected plants','Pull out mottled plants, handling them last.','Every touch spreads the virus.','GrabAndRemove',1,0,-2.000000029802322388e-01,-1.0000000149011611938e-01,0.0,-1.0000000149011611938e-01,0.0,0.0);
INSERT INTO "treatment_steps" VALUES('tobacco','mosaic_virus','tobacco_mosaic_virus_1',20,'Wash hands and tools','Wash with soap and disinfect tools between plants.','The virus spreads on hands and tools.','AdjustSetting',1,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('tobacco','mosaic_virus','tobacco_mosaic_virus_2',30,'Plan resistant varieties','Choose resistant varieties next season.','The main control.','Informational',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('wheat','bacterial_leaf_streak','wheat_bacterial_leaf_streak_0',10,'Confirm with the ooze','Look for shiny dried ooze flakes on the streaks.','Separates it from fungal streaks.','TapRegion',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('wheat','bacterial_leaf_streak','wheat_bacterial_leaf_streak_1',20,'Plan clean seed','Use seed from healthy fields.','Seed carries the bacteria.','Informational',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('wheat','bacterial_leaf_streak','wheat_bacterial_leaf_streak_2',30,'Rotate crops','Leave a year away from wheat and barley.','Residue carries it.','AdjustSetting',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('wheat','head_scab','wheat_head_scab_0',10,'Note how many heads are bleached','Count affected heads.','Guides harvest and grain testing.','TapRegion',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('wheat','head_scab','wheat_head_scab_1',20,'Protective spray','Spray a registered fungicide at early flowering on the label''s schedule.','Only flowering-time sprays help.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('wheat','head_scab','wheat_head_scab_2',30,'Test the grain','Have harvested grain tested for mycotoxins.','Contaminated grain is a health risk.','Informational',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
INSERT INTO "treatment_steps" VALUES('wheat','leaf_rust','wheat_leaf_rust_0',10,'Scout the upper leaves','Check the flag leaf and the leaf below it.','These leaves feed the grain.','TapRegion',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('wheat','leaf_rust','wheat_leaf_rust_1',20,'Protective spray','Spray a registered fungicide if rust reaches the upper leaves on the label''s schedule.','Protects healthy growth; it cannot cure what is already infected.','SprayApply',3,1,-1.7000000178813934326e-01,-1.7000000178813934326e-01,0.0,0.0,0.0,5.999999865889549256e-02);
