INSERT INTO "treatment_steps" VALUES('wheat','loose_smut','wheat_loose_smut_0',10,'Note the infected heads','Count smutted heads.','Shows how much seed is infected.','TapRegion',1,0,-5.000000074505805969e-02,0.0,0.0,0.0,0.0,2.999999932944774628e-02);
INSERT INTO "treatment_steps" VALUES('wheat','loose_smut','wheat_loose_smut_1',20,'Do not save seed from this field','Use certified or treated seed next time.','The fungus is inside the seed.','Informational',2,0,-7.999999821186065673e-02,0.0,-3.999999910593032836e-02,0.0,0.0,5.999999865889549256e-02);
